import { useCallback, useState } from "react"
import { getAdminParams } from "@/lib/admin-params"
import { useUpgradeReloadPreparation } from "@/lib/upgrade-reload"

/** Upgrade reload checkpoints are browser-tab-local and scoped to this user/conversation. */
export function useChatComposerDraft(scope: string): [string, (value: string) => void] {
  const params = getAdminParams()
  const key = `mapsvg:composer:${encodeURIComponent(params.homeUrl)}:${params.user?.id ?? "current"}:${scope}`
  const read = () => {
    try {
      return sessionStorage.getItem(key) ?? ""
    } catch {
      return ""
    }
  }
  const [state, setState] = useState(() => ({ key, value: read() }))
  const value = state.key === key ? state.value : read()
  const change = useCallback(
    (next: string) => {
      // Sending/editing after a failed reload preparation retires the old checkpoint.
      try {
        sessionStorage.removeItem(key)
      } catch {
        /* The explicit reload guard reports storage failure. */
      }
      setState({ key, value: next })
    },
    [key],
  )
  useUpgradeReloadPreparation(() => {
    try {
      if (value) sessionStorage.setItem(key, value)
      else sessionStorage.removeItem(key)
    } catch {
      if (value)
        throw new Error(
          "Your unsent chat message could not be saved locally. Copy or send it before reloading the editor.",
        )
    }
  })
  return [value, change]
}
