/** Display guard for older saved replies and malformed provider protocol. Never executes tools. */
export function aiDisplayText(content: string): string {
  const prefix = String.raw`(?:[|｜]\s*){1,2}DSML\s*(?:[|｜]\s*){1,2}`
  if (!new RegExp(String.raw`<\s*\/?\s*${prefix}`, "iu").test(content)) return content
  return content
    .replace(new RegExp(String.raw`<\s*${prefix}(tool_calls|function_calls|calls|invoke)\b[^>]*>.*?(?:<\s*\/\s*${prefix}\1\s*>|$)`, "gisu"), "")
    .replace(new RegExp(String.raw`<\s*${prefix}.*$`, "gisu"), "")
    .replace(new RegExp(String.raw`<\s*\/\s*${prefix}[^>]*(?:>|$)`, "gisu"), "")
    .replace(/<\s*(?:[|｜]\s*){1,2}end[^>]*>/giu, "")
    .replace(/```(?:xml)?\s*```/gi, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim()
}
