import { resourceApiUrl } from "@/lib/resource-api-url"

/** Keep route and query parameters separate for both WordPress permalink modes. */
export function aiApiUrl(base: string, path: string): string {
  const queryStart = path.indexOf("?")
  const route = queryStart < 0 ? path : path.slice(0, queryStart)
  const url = resourceApiUrl(base, route.startsWith("/") ? route : `/${route}`)
  if (queryStart < 0) return url
  const split = url.indexOf("?")
  const pathname = split < 0 ? url : url.slice(0, split)
  const params = new URLSearchParams(split < 0 ? "" : url.slice(split + 1))
  for (const [key, value] of new URLSearchParams(path.slice(queryStart + 1))) params.set(key, value)
  return pathname + "?" + params.toString()
}
