import { getAdminParams } from "@/lib/admin-params"
import type { AiDraftState, AiDraftAction } from "@/lib/ai-draft-actions"
import type { AiChatMessage, AiTaskPlan } from "./ai-api"
import { aiApiUrl } from "./ai-api-url"

export type AiStreamEvent =
  | {type:"chat_title";chatId:number;title:string;mapId:number|null}
  | { type: "svg_regions_preview" | "svg_regions_apply_request"; analysisId: string; mapId: number; draftId: number }
  | { type: "status"; phase: "assessing" | "executing" | "replying"; text: string }
  | { type: "assessment"; text: string; mode: string; effort: "none" | "medium" }
  | { type: "task_plan"; plan: AiTaskPlan }
  | { type: "text_delta"; text: string }
  | { type: "error"; error: string }
  | { type: "done"; provider?: string; model?: string }
  | { type: "publish_request"; mapId?: number }
  | { type: "draft_action_request"; mapId?: number; draftId?: number; action?: AiDraftAction }
  | {
      type: "tool_call"
      id?: string
      name?: string
      arguments?: Record<string, unknown>
    }
  | {
      type: "tool_result"
      id?: string
      name?: string
      ok?: boolean
      result?: unknown
      error?: string | null
    }
  | {
      type: "options_patch"
      mapId?: number
      patch?: Record<string, unknown>
    }
  | {
      type: "options_replace"
      mapId?: number
      options?: Record<string, unknown>
    }
  | {
      type: "map_mutation"
      action?: "created" | "duplicated" | "renamed" | "deleted" | "published"
      map?: { mapId?: number; title?: string }
    }
  | {
      type: "schema_mutation"
      action?: "created" | "updated" | "deleted"
      schema?: { id?: number; name?: string; title?: string; type?: string }
    }
  | {
      type: "repository_mutation"
      action?: "created" | "updated" | "deleted" | "cleared"
      schema?: string
      recordId?: unknown
    }
  | {
      type: "query_mutation"
      action?:
        | "created"
        | "updated"
        | "deleted"
        | "folder_created"
        | "folder_updated"
        | "folder_deleted"
      query?: Record<string, unknown>
      folder?: Record<string, unknown>
    }
  | {
      type: "connection_mutation"
      action?: "connected" | "disconnected"
      schemaId?: number | null
      mapId?: number
      linked?: boolean
    }
  | {
      type: "global_settings_mutation"
      settings?: Record<string, unknown>
    }
  | {
      type: "open_map"
      mapId?: number
      title?: string
    }
  | { type: string; [key: string]: unknown }

type StreamAiChatArgs = {
  messages: AiChatMessage[]
  chatId?: number | null
  mapId?: number | null
  previewState?: { mapId: number; options: Record<string, unknown>; draft?: AiDraftState | null } | null
  signal?: AbortSignal
  onEvent: (event: AiStreamEvent) => void
}

function apiBase(): { base: string; nonce: string } {
  const p = getAdminParams()
  return { base: p.apiUrl, nonce: p.nonce }
}

/**
 * POST /ai/chat with SSE (stream: true). Parses `data: {json}` lines.
 */
export async function streamAiChat({
  messages,
  chatId,
  mapId,
  previewState,
  signal,
  onEvent,
}: StreamAiChatArgs): Promise<void> {
  const { base, nonce } = apiBase()
  const res = await fetch(aiApiUrl(base, "/ai/chat"), {
    method: "POST",
    headers: {
      Accept: "text/event-stream",
      "Content-Type": "application/json",
      "X-WP-Nonce": nonce,
    },
    credentials: "same-origin",
    signal,
    body: JSON.stringify({
      messages,
      chatId: chatId ?? undefined,
      mapId: mapId ?? undefined,
      previewState: previewState ?? undefined,
      stream: true,
    }),
  })

  if (!res.ok) {
    let message = `API ${res.status}: /ai/chat`
    try {
      const data = (await res.json()) as { error?: string }
      if (data?.error) message = data.error
    } catch {
      // ignore
    }
    throw new Error(message)
  }

  if (!res.body) {
    throw new Error("Streaming is not supported in this browser.")
  }

  const reader = res.body.getReader()
  const decoder = new TextDecoder()
  let buffer = ""
  let completed = false

  const lineEvent = (line: string) => {
    const trimmed = line.trim()
    if (trimmed === "" || trimmed.startsWith(":")) return
    if (!trimmed.startsWith("data:")) return
    const data = trimmed.slice(5).trim()
    if (data === "[DONE]") {
      if (!completed) onEvent({ type: "done" })
      completed = true
      return
    }
    let parsed: AiStreamEvent
    try { parsed = JSON.parse(data) as AiStreamEvent }
    catch { throw new Error("Invalid AI stream event. Completed changes are retained.") }
    if (!parsed || typeof parsed.type !== "string") throw new Error("Invalid AI stream event.")
    if (parsed.type === "done") completed = true
    onEvent(parsed)
  }
  try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) {
        buffer += decoder.decode()
        if (buffer.trim()) lineEvent(buffer)
        break
      }
      buffer += decoder.decode(value, { stream: true })
      let sep: number
      while ((sep = buffer.indexOf("\n")) !== -1) {
        lineEvent(buffer.slice(0, sep))
        buffer = buffer.slice(sep + 1)
      }
      if (buffer.length > 2_000_000) throw new Error("AI stream event is too large.")
    }
    if (!completed) throw new Error("The AI stream ended early. Completed changes are retained; send a new message to continue.")
  } finally {
    // Handler/parse failures must not leave an unread connection alive. Dashboard
    // owns draining and accounting any already-started provider invocation.
    try { await reader.cancel() } catch { /* aborted connection */ }
    reader.releaseLock()
  }
}
