type ChatRole = "user" | "assistant" | "tool"

type ChatMessage = {
  id: string
  dbId?: number
  role: ChatRole
  content: string
  stage?: AiToolStage
}

type ChatThread = {
  taskPlan?: AiTaskPlan | null
  id: string
  title: string
  messages: ChatMessage[]
  updatedAt: number
  persistedId: number | null
  hasMore?: boolean
  messageCount?: number
}

const DEFAULT_TITLE = "New chat"
const AI_CONTEXT_WINDOW_MESSAGES = 50

function titleFromMessage(text: string): string {
  const trimmed = text.trim().replace(/\s+/g, " ")
  if (trimmed.length <= 48) return trimmed
  return `${trimmed.slice(0, 45)}…`
}

function toUpdatedAtMs(iso: string): number {
  const t = Date.parse(iso)
  return Number.isFinite(t) ? t : Date.now()
}

function listItemToThread(item: AiPersistedChatListItem): ChatThread {
  return {
    id: `db-${item.id}`,
    persistedId: item.id,
    title: item.title || DEFAULT_TITLE,
    messages: [],
    updatedAt: toUpdatedAtMs(item.updatedAt),
  }
}

function persistedToChatMessages(
  messages: AiPersistedChat["messages"],
): ChatMessage[] {
  return messages.map((m) => ({
    id: m.id,
    dbId: m.dbId,
    role: m.role,
    content: m.content,
  }))
}

function applyChatPage(
  thread: ChatThread,
  full: AiPersistedChat,
  prepend = false,
): ChatThread {
  const incoming = persistedToChatMessages(full.messages)
  const messages = prepend ? [...incoming, ...thread.messages] : incoming
  return {
    ...thread,
    title: full.title,
    taskPlan: full.taskPlan ?? null,
    messages,
    updatedAt: toUpdatedAtMs(full.updatedAt),
    hasMore: Boolean(full.hasMore),
    messageCount: full.messageCount ?? incoming.length,
  }
}

function oldestDbId(messages: ChatMessage[]): number | null {
  for (const m of messages) {
    if (m.dbId) return m.dbId
  }
  return null
}

function unsavedMessages(messages: ChatMessage[]): ChatMessage[] {
  return messages.filter(
    (m) =>
      !m.dbId &&
      !(m.role === "assistant" && m.content.trim() === ""),
  )
}

function mergeDbIds(
  local: ChatMessage[],
  fromServer: AiPersistedChat["messages"],
): ChatMessage[] {
  const byClientId = new Map(fromServer.map((m) => [m.id, m.dbId]))
  return local.map((m) => ({
    ...m,
    dbId: m.dbId ?? byClientId.get(m.id),
  }))
}

type Props = {
  mapId?: number | null
  className?: string
}

/**
 * AI map-building assistant — one persistent chat per map.
 */
export function AiChatPanel({ mapId = null, className }: Props) {
  const [thread, setThread] = useState<ChatThread | null>(null)
  const [input, setInput] = useChatComposerDraft(`map:${mapId ?? "none"}`)
  const bootSettings = useBootAiSettings()
  const [aiSettings, setAiSettings] = useState<AiPublicSettings>(bootSettings)
  const [showSettings, setShowSettings] = useState(() => !bootSettings.configured)
  useEffect(() => {
    setAiSettings(bootSettings)
    setShowSettings(!bootSettings.configured)
  }, [bootSettings])
  const [sending, setSending] = useState(false)
  useUpgradeReloadGuard(sending, "Wait for the current AI request to finish before reloading the editor.")
  const [statusText, setStatusText] = useState<string | null>(null)
  const [loadingChats, setLoadingChats] = useState(false)
  const [loadingEarlier, setLoadingEarlier] = useState(false)
  const [loadError, setLoadError] = useState<string | null>(null)
  const abortRef = useRef<AbortController | null>(null)
  /** Latest messages for the in-flight send (avoids React batch race on persist). */
  const workingMessagesRef = useRef<ChatMessage[] | null>(null)

  const streamingAssistantId = useMemo(() => {
    if (!sending || !thread) return undefined
    for (let i = thread.messages.length - 1; i >= 0; i--) {
      if (thread.messages[i].role === "assistant") {
        return thread.messages[i].id
      }
    }
    return undefined
  }, [sending, thread])

  const transcriptScrollKey = useMemo(() => {
    if (!thread) return `empty:${mapId ?? "none"}`
    return [
      thread.id,
      statusText,
      `${thread.taskPlan?.id}:${thread.taskPlan?.running}:${thread.taskPlan?.steps.map(step => `${step.status}:${step.note.length}`).join(",")}`,
      ...thread.messages.map(
        (message) => `${message.id}:${message.content.length}`,
      ),
    ].join("|")
  }, [mapId, thread, statusText])

  const abortActive = useCallback(() => {
    abortRef.current?.abort()
    abortRef.current = null
  }, [])

  useEffect(() => () => abortActive(), [abortActive])

  // A map has one persistent chat. Opening a map only loads it; the chat is
  // created lazily when the user sends the first message.
  useEffect(() => {
    abortActive()
    setSending(false)
    setStatusText(null)
    setLoadError(null)

    setThread(null)

    if (!mapId) {
      setLoadingChats(false)
      return
    }

    let cancelled = false
    setLoadingChats(true)

    void (async () => {
      try {
        const items = await fetchAiChats(mapId)
        if (cancelled) return

        const latest = items[0]
        if (!latest) return

        const full = await fetchAiChat(latest.id)
        if (cancelled) return
        setThread(applyChatPage(listItemToThread(latest), full))
      } catch (err) {
        if (cancelled) return
        setLoadError(err instanceof Error ? err.message : String(err))
        setThread(null)
      } finally {
        if (!cancelled) setLoadingChats(false)
      }
    })()

    return () => {
      cancelled = true
    }
  }, [mapId, abortActive])

  const loadEarlier = useCallback(async () => {
    if (!thread?.persistedId || !thread.hasMore || loadingEarlier) return
    const beforeId = oldestDbId(thread.messages)
    if (!beforeId) return

    setLoadingEarlier(true)
    try {
      const page = await fetchAiChat(thread.persistedId, { beforeId })
      setThread((current) =>
        current?.persistedId === page.id
          ? applyChatPage(current, page, true)
          : current,
      )
    } catch (err) {
      console.error("[mapsvg-admin-react] Failed to load earlier messages", err)
      setLoadError(err instanceof Error ? err.message : String(err))
    } finally {
      setLoadingEarlier(false)
    }
  }, [thread, loadingEarlier])

  const upsertMessage = useCallback((chatId: string, message: ChatMessage) => {
    if (workingMessagesRef.current) {
      const idx = workingMessagesRef.current.findIndex((m) => m.id === message.id)
      workingMessagesRef.current =
        idx === -1
          ? [...workingMessagesRef.current, message]
          : workingMessagesRef.current.map((m, i) =>
              i === idx ? message : m,
            )
    }
    setThread((current) => {
      if (!current || current.id !== chatId) return current
      const idx = current.messages.findIndex((m) => m.id === message.id)
      const messages =
        idx === -1
          ? [...current.messages, message]
          : current.messages.map((m, i) => (i === idx ? message : m))
      return { ...current, updatedAt: Date.now(), messages }
    })
  }, [])

  const patchAssistant = useCallback(
    (
      chatId: string,
      assistantId: string,
      updater: (content: string) => string,
    ) => {
      if (workingMessagesRef.current) {
        workingMessagesRef.current = workingMessagesRef.current.map((m) =>
          m.id === assistantId ? { ...m, content: updater(m.content) } : m,
        )
      }
      setThread((current) => {
        if (!current || current.id !== chatId) return current
        return {
          ...current,
          updatedAt: Date.now(),
          messages: current.messages.map((m) =>
            m.id === assistantId
              ? { ...m, content: updater(m.content) }
              : m,
          ),
        }
      })
    },
    [],
  )

  const send = useCallback(async (attachments: AiAttachment[] = []) => {
    const promptText = input.trim()
    const text = withAttachments(promptText, attachments)
    if (!text || !mapId || sending || loadingChats) return

    if (!aiSettings.configured) {
      setShowSettings(true)
      return
    }

    abortActive()
    const ac = new AbortController()
    abortRef.current = ac

    const userMessage: ChatMessage = {
      id: `user-${Date.now()}`,
      role: "user",
      content: text,
    }

    let activeThread = thread
    const history = (activeThread?.messages ?? [])
      .filter((m) => m.role !== "tool" && m.content.trim())
      .slice(-AI_CONTEXT_WINDOW_MESSAGES)
    const nextTitle =
      history.length === 0
        ? titleFromMessage(
            promptText || attachments.map((item) => item.name).join(", "),
          )
        : activeThread?.title || DEFAULT_TITLE

    const assistantId = `assistant-${Date.now()}`
    activeThread = {
      ...(activeThread ?? {
        id: `local-${userMessage.id}`,
        persistedId: null,
        title: nextTitle,
        updatedAt: Date.now(),
      }),
      messages: [
        ...(activeThread?.messages ?? []).filter(m => m.role !== "assistant" || m.content.trim()),
        userMessage,
        { id: assistantId, role: "assistant", content: "" },
      ],
    }
    // Render this turn before persistence; the server response only reconciles IDs.
    workingMessagesRef.current = activeThread.messages
    setThread(activeThread)

    setInput("")
    setSending(true)
    setLoadError(null)
    setStatusText(initialAiStatus(promptText, history))

    try {
      const appendMessages = unsavedMessages(activeThread.messages).map(({ id, role, content }) => ({ id, role, content }))
      if (!activeThread.persistedId) {
        const created = await createAiChat({
          mapId,
          messages: appendMessages,
        })
        activeThread = {
          ...activeThread,
          persistedId: created.id,
          title: created.title || nextTitle,
          messages: mergeDbIds(activeThread.messages, created.messages),
          updatedAt: toUpdatedAtMs(created.updatedAt),
          hasMore: Boolean(created.hasMore),
          messageCount: created.messageCount,
        }
      } else {
        const savedUserTurn = await updateAiChat(activeThread.persistedId, {
          appendMessages,
        })
        activeThread = {
          ...activeThread,
          title: savedUserTurn.title,
          messages: mergeDbIds(
            activeThread.messages,
            savedUserTurn.messages,
          ),
          hasMore: Boolean(savedUserTurn.hasMore),
          messageCount: savedUserTurn.messageCount,
          updatedAt: toUpdatedAtMs(savedUserTurn.updatedAt),
        }
      }
    } catch (err) {
      if (ac.signal.aborted || abortRef.current !== ac) return
      abortRef.current = null
      setStatusText(null)
      setSending(false)
      setLoadError(err instanceof Error ? err.message : String(err))
      return
    }

    if (ac.signal.aborted || abortRef.current !== ac || !activeThread.persistedId) return
    setThread(activeThread)

    const chatId = activeThread.id
    const seedMessages = activeThread.messages
    let lastTurnMessages = seedMessages
    workingMessagesRef.current = seedMessages
    setThread({ ...activeThread, messages: seedMessages })

    let gotText = false
    let gotError = false
    let previewApplyFailed = false
    const publishDraftId = mapId ? getAppDraftSession(mapId).activeId : null
    let publishRequested = false
    const browserDraft = getAiDraftState(mapId)
    const browserPreview = getAdminMapPreviewState(mapId)
    let draftAction: AiDraftAction | null = null
    let incompatibleActions = false
    let svgApplication: Promise<void> | null = null
    const svgAnalysisIds = new Set<string>()
    const enqueueSvgRegion = createSvgRegionQueue(applySvgRegionProposal)
    const pendingMapMutations: Array<{
      action: "created" | "duplicated" | "renamed" | "deleted" | "published"
      map: { mapId: number; title: string }
    }> = []
    const pendingSchemaMutations: Array<{
      action: "created" | "updated" | "deleted"
      schema: { id: number; name: string; title: string; type: string }
    }> = []
    const pendingRepositoryMutations: Array<{
      action: "created" | "updated" | "deleted" | "cleared"
      schema: string
      recordId?: unknown
    }> = []
    const pendingQueryMutations: Array<Record<string, unknown>> = []
    const pendingConnectionMutations: Array<{
      action: "connected" | "disconnected"
      schemaId?: number | null
      mapId: number
      linked?: boolean
    }> = []
    let pendingOpenMap: { mapId: number; title: string } | null = null
    const getPendingOpenMap = (): { mapId: number; title: string } | null => pendingOpenMap

    try {
      await streamAiChat({
        chatId: activeThread.persistedId,
        mapId,
        previewState: browserPreview ? { ...browserPreview, draft: browserDraft } : null,
        signal: ac.signal,
        messages: [...history, userMessage].map((m) => ({
          role: m.role as "user" | "assistant",
          content: m.content,
        })),
        onEvent: (event) => {
          if (ac.signal.aborted || abortRef.current !== ac) return
          if(event.type==="chat_title"){
            notifyProjectChat({id:Number(event.chatId),mapId:typeof event.mapId==="number"?event.mapId:null,title:String(event.title),createdAt:"",updatedAt:new Date().toISOString()})
          } else if (event.type === "status" && typeof event.text === "string") {
            setStatusText(initialAiStatus(promptText, history))
          } else if (event.type === "task_plan") {
            setThread(current => current?.id === chatId ? { ...current, taskPlan: { ...(event.plan as AiTaskPlan), userMessageId: userMessage.id } } : current)
          } else if (event.type === "text_delta" && typeof event.text === "string") {
            setStatusText(null)
            gotText = true
            patchAssistant(chatId, assistantId, (c) => c + event.text)
          } else if (
            event.type === "error" &&
            typeof event.error === "string"
          ) {
            setStatusText(null)
            gotError = true
            patchAssistant(chatId, assistantId, (c) =>
              c ? `${c}\n\nError: ${event.error}` : `Error: ${event.error}`,
            )
          } else if (event.type === "tool_call") {
            setStatusText(initialAiStatus(promptText, history))
            const id = String(event.id || `tool-${Date.now()}`)
            const name = String(event.name || "tool")
            if (isQuietAiTool(name)) return
            upsertMessage(chatId, {
              id,
              role: "tool",
              stage: "tool_running",
              content: `Calling ${name}`,
            })
          } else if (event.type === "tool_result") {
            const id = String(event.id || `tool-${Date.now()}`)
            const name = String(event.name || "tool")
            if (isQuietAiTool(name)) return
            const ok = Boolean(event.ok)
            const err =
              typeof event.error === "string" && event.error
                ? event.error
                : null
            upsertMessage(chatId, {
              id,
              role: "tool",
              stage: ok ? "tool_done" : "tool_error",
              content: ok
                ? `Ran ${name}`
                : `Failed ${name}${err ? `: ${err}` : ""}`,
            })
          } else if (event.type === "done") {
            setStatusText(null)
          } else if (event.type === "options_patch" && event.patch) {
            const patch = event.patch
            const applied =
              event.mapId === mapId &&
              typeof patch === "object" &&
              !Array.isArray(patch) &&
              applyOptionsPatchToLiveMap(patch as Record<string, unknown>)
            if (!applied) {
              gotError = true
              previewApplyFailed = true
            }
            upsertMessage(chatId, {
              id: `patch-${Date.now()}`,
              role: "tool",
              stage: applied ? "options_patch" : "tool_error",
              content: applied
                ? "Updated map options (preview)"
                : "Failed to update map preview. Check that this map is open and try again.",
            })
          } else if (
            event.type === "options_replace" &&
            event.mapId === mapId &&
            event.options &&
            typeof event.options === "object" &&
            !Array.isArray(event.options)
          ) {
            window.dispatchEvent(
              new CustomEvent("mapsvg:options-replace", {
                detail: { mapId, options: event.options },
              }),
            )
            upsertMessage(chatId, {
              id: `replace-${Date.now()}`,
              role: "tool",
              stage: "options_patch",
              content: "Replaced map options (preview)",
            })
          } else if (event.type === "svg_regions_apply_request") {
            const target = typeof event.analysisId === "string" && typeof event.mapId === "number" && typeof event.draftId === "number"
              ? { analysisId: event.analysisId, mapId: event.mapId, draftId: event.draftId } : null
            if (!target || target.mapId !== mapId || target.draftId !== browserDraft?.draftId) {
              gotError = true; incompatibleActions = true
            } else if (!svgAnalysisIds.has(target.analysisId)) {
              svgAnalysisIds.add(target.analysisId)
              // Multiple analysis/refinement stages may add disjoint zones in one turn.
              // Serialize native Save/sync and deduplicate each immutable proposal.
              svgApplication = enqueueSvgRegion(target).then(result => {
                upsertMessage(chatId, { id: `svg-${event.analysisId}`, role: "tool", stage: "tool_done", content: `Saved ${result.count} SVG regions in the draft. Not published.` })
              }, async error => {
                gotError = true
                // A queued successor must not remain pending after an earlier save failed.
                await regionProposal(target, "failed").catch(() => {})
                const message = `SVG application failed: ${error instanceof Error ? error.message : String(error)}. Inspect the retained draft before retrying.`
                upsertMessage(chatId, { id: `svg-${event.analysisId}`, role: "tool", stage: "tool_error", content: message })
                patchAssistant(chatId, assistantId, content => `${content}${content ? "\n\n" : ""}${message}`)
              })
            }
          } else if (event.type === "draft_action_request") {
            if (event.mapId === mapId && event.draftId === browserDraft?.draftId
              && (event.action === "pull_changes" || event.action === "branch")) {
              if (draftAction && draftAction !== event.action) incompatibleActions = true
              draftAction = event.action
            } else incompatibleActions = true
          } else if (event.type === "publish_request") {
            if (event.mapId === mapId) publishRequested = true
          } else if (event.type === "map_mutation") {
            const mutation = event as {
              action?: "created" | "duplicated" | "renamed" | "deleted" | "published"
              map?: { mapId?: number; title?: string }
            }
            if (
              mutation.action &&
              (mutation.action === "created" ||
                mutation.action === "duplicated" ||
                mutation.action === "renamed" ||
                mutation.action === "deleted" ||
                mutation.action === "published") &&
              typeof mutation.map?.mapId === "number"
            ) {
              pendingMapMutations.push({
                action: mutation.action,
                map: {
                  mapId: mutation.map.mapId,
                  title:
                    typeof mutation.map.title === "string" && mutation.map.title
                      ? mutation.map.title
                      : `Map #${mutation.map.mapId}`,
                },
              })
            }
          } else if (event.type === "schema_mutation") {
            const mutation = event as {
              action?: "created" | "updated" | "deleted"
              schema?: { id?: number; name?: string; title?: string; type?: string }
            }
            if (
              mutation.action &&
              (mutation.action === "created" ||
                mutation.action === "updated" ||
                mutation.action === "deleted") &&
              typeof mutation.schema?.id === "number"
            ) {
              pendingSchemaMutations.push({
                action: mutation.action,
                schema: {
                  id: mutation.schema.id,
                  name: mutation.schema.name || "",
                  title: mutation.schema.title || "",
                  type: mutation.schema.type || "",
                },
              })
            }
          } else if (event.type === "repository_mutation") {
            const mutation = event as {
              action?: "created" | "updated" | "deleted" | "cleared"
              schema?: string
              recordId?: unknown
            }
            if (
              mutation.action &&
              (mutation.action === "created" ||
                mutation.action === "updated" ||
                mutation.action === "deleted" ||
                mutation.action === "cleared") &&
              typeof mutation.schema === "string"
            ) {
              pendingRepositoryMutations.push({
                action: mutation.action,
                schema: mutation.schema,
                recordId: mutation.recordId,
              })
            }
          } else if (event.type === "query_mutation") {
            pendingQueryMutations.push(event as Record<string, unknown>)
          } else if (event.type === "connection_mutation") {
            const mutation = event as {
              action?: "connected" | "disconnected"
              schemaId?: number | null
              mapId?: number
              linked?: boolean
            }
            if (
              mutation.action &&
              (mutation.action === "connected" || mutation.action === "disconnected") &&
              typeof mutation.mapId === "number"
            ) {
              pendingConnectionMutations.push({
                action: mutation.action,
                schemaId: mutation.schemaId,
                mapId: mutation.mapId,
                linked: mutation.linked,
              })
            }
          } else if (event.type === "global_settings_mutation") {
            const mutation = event as { settings?: Record<string, unknown> }
            if (mutation.settings) {
              window.dispatchEvent(
                new CustomEvent("mapsvg:global-settings-mutation", {
                  detail: { settings: mutation.settings },
                }),
              )
            }
          } else if (
            event.type === "open_map" &&
            typeof event.mapId === "number"
          ) {
            pendingOpenMap = {
              mapId: event.mapId,
              title:
                typeof event.title === "string" && event.title
                  ? event.title
                  : `Map #${event.mapId}`,
            }
          }
          lastTurnMessages = workingMessagesRef.current ?? lastTurnMessages
        },
      })
      if (svgApplication) await svgApplication
      if (incompatibleActions || (draftAction && publishRequested) || (svgApplication && (draftAction || publishRequested))) {
        gotError = true
        patchAssistant(chatId, assistantId, content => `${content}${content ? "\n\n" : ""}Draft actions were not started. Request Pull, Branch or Publish separately.`)
      }
      if (draftAction && !incompatibleActions && !publishRequested && !ac.signal.aborted) {
        const result = !gotError && !previewApplyFailed && browserDraft
          ? await requestAiDraftAction({ mapId: browserDraft.mapId, draftId: browserDraft.draftId, action: draftAction })
          : { status: "rejected" as const }
        const accepted = result.status === "completed" || result.status === "confirmation_required"
        if (!accepted) gotError = true
        const message = result.status === "confirmation_required" ? "Pull changes confirmation opened. Local edits are retained until you confirm."
          : result.status === "completed" ? `Local copy branched into draft #${result.draftId}.`
          : "Draft action failed or is no longer available. Your local copy is retained. Keep the same draft open and check the connection."
        upsertMessage(chatId, { id: `draft-action-${Date.now()}`, role: "tool", stage: accepted ? "tool_done" : "tool_error", content: message })
        if (!accepted) patchAssistant(chatId, assistantId, content => `${content}${content ? "\n\n" : ""}${message}`)
      }
      if (publishRequested && !ac.signal.aborted) {
        const result = !gotError && !previewApplyFailed && mapId != null && publishDraftId != null
          ? await requestAiPublish({ mapId, draftId: publishDraftId })
          : { status: "rejected" as const }
        const completed = result.status === "completed"
        if (!completed) gotError = true
        const message = completed ? `Published version ${result.versionId}. The map on the front-end page is updated.`
          : result.status === "failed" ? `Publish failed${result.message ? `: ${result.message}` : "."} Your draft is retained.`
          : "Publish was not started. Keep the same draft open and resolve offline or conflict errors before retrying."
        upsertMessage(chatId, {
          id: `publish-${Date.now()}`, role: "tool", stage: completed ? "tool_done" : "tool_error", content: message,
        })
        patchAssistant(chatId, assistantId, content => `${content}${content ? "\n\n" : ""}${message}`)
      }
      if (previewApplyFailed) {
        patchAssistant(chatId, assistantId, (content) =>
          `${content}${content ? "\n\n" : ""}Preview update failed in the browser. Check the map before saving.`,
        )
      }
      if (!gotText && !gotError && !ac.signal.aborted) {
        patchAssistant(chatId, assistantId, (c) => c || "")
      }
    } catch (err) {
      if (ac.signal.aborted) return
      setStatusText(null)
      const msg = err instanceof Error ? err.message : String(err)
      patchAssistant(chatId, assistantId, (c) =>
        c ? `${c}\n\nError: ${msg}` : `Error: ${msg}`,
      )
    } finally {
      const ownsRequest = abortRef.current === ac
      const finalMessages = ownsRequest ? workingMessagesRef.current : lastTurnMessages
      const openMap = !ac.signal.aborted ? getPendingOpenMap() : null
      if (ownsRequest) workingMessagesRef.current = null

      // Persisted server mutations must reach the UI even when the stream was
      // aborted after a tool had already completed.
      for (const mutation of pendingMapMutations) {
        window.dispatchEvent(
          new CustomEvent("mapsvg:map-mutation", { detail: mutation }),
        )
      }
      for (const mutation of pendingSchemaMutations) {
        window.dispatchEvent(
          new CustomEvent("mapsvg:schema-mutation", { detail: mutation }),
        )
      }
      for (const mutation of pendingRepositoryMutations) {
        window.dispatchEvent(
          new CustomEvent("mapsvg:repository-mutation", { detail: mutation }),
        )
      }
      for (const mutation of pendingQueryMutations) {
        window.dispatchEvent(
          new CustomEvent("mapsvg:query-mutation", { detail: mutation }),
        )
      }
      for (const mutation of pendingConnectionMutations) {
        window.dispatchEvent(
          new CustomEvent("mapsvg:connection-mutation", { detail: mutation }),
        )
      }

      if (finalMessages) {
        const toSave = finalMessages
        const append = unsavedMessages(toSave)

        setThread((current) =>
          current?.persistedId === activeThread.persistedId
            ? { ...current, title: nextTitle, messages: toSave, updatedAt: Date.now() }
            : current,
        )

        if (append.length > 0 || openMap) {
          try {
            const saved = await updateAiChat(activeThread.persistedId, {
              ...(openMap ? { mapId: openMap.mapId } : {}),
              ...(append.length > 0
                ? {
                    appendMessages: append.map((m) => ({
                      id: m.id,
                      role: m.role,
                      content: m.content,
                    })),
                  }
                : {}),
            })
            setThread((current) =>
              current?.persistedId === activeThread.persistedId
                ? {
                    ...current,
                    messages: mergeDbIds(toSave, saved.messages),
                    hasMore: Boolean(saved.hasMore),
                    messageCount: saved.messageCount,
                    updatedAt: toUpdatedAtMs(saved.updatedAt),
                  }
                : current,
            )
          } catch (err) {
            console.error("[mapsvg-admin-react] Failed to save AI chat", err)
            setLoadError(err instanceof Error ? err.message : String(err))
          }
        }
      }

      if (openMap) {
        window.dispatchEvent(
          new CustomEvent("mapsvg:open-map", { detail: openMap }),
        )
      }

      if (abortRef.current === ac) {
        abortRef.current = null
        setStatusText(null)
        setSending(false)
      }
    }
  }, [
    input,
    thread,
    mapId,
    sending,
    loadingChats,
    aiSettings.configured,
    abortActive,
    patchAssistant,
    upsertMessage,
  ])

  const emptyDescription = !mapId
    ? "Select a map to use its AI chat."
    : loadingChats
      ? "Loading chat…"
      : loadError
        ? loadError
        : aiSettings.configured
          ? null
          : "Activate your MapSVG license in Usage to start."

  const progressLabel = sending ? currentAiStep(thread?.taskPlan, thread?.messages ?? [], statusText) : null

  return (
    <div className={cn("relative flex h-full min-h-0 flex-col", className)} data-ai-chat-overlay>
      {showSettings ? (
        <div className="shrink-0 border-b border-border p-3">
          <AiSettingsForm
            settings={aiSettings}
            onSaved={(next) => {
              setAiSettings(next)
              if (next.configured) setShowSettings(false)
            }}
          />
        </div>
      ) : null}

      <AiTranscriptScroll scrollKey={transcriptScrollKey}>
        <AiQuotaScope key={`chat:${thread?.persistedId ?? `new-map-${mapId}`}`} scope={`chat:${thread?.persistedId ?? `new-map-${mapId}`}`}>
        {thread?.hasMore ? (
          <div className="flex justify-center">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              disabled={loadingEarlier}
              onClick={() => void loadEarlier()}
            >
              {loadingEarlier ? "Loading…" : "Load earlier messages"}
            </Button>
          </div>
        ) : null}

        {!thread || thread.messages.length === 0 ? (
          <div className="flex min-h-full flex-1 flex-col items-center justify-center">
            <Empty className="border-0 md:p-6">
              <EmptyHeader>
                <EmptyTitle className="text-xl">
                  {!mapId ? "Select a map" : "How can I help you today?"}
                </EmptyTitle>
                {emptyDescription ? <EmptyDescription>{emptyDescription}</EmptyDescription> : null}
              </EmptyHeader>
              {mapId && !aiSettings.configured ? (
                <EmptyContent>
                  <Button
                    type="button"
                    size="sm"
                    onClick={() => setShowSettings(true)}
                  >
                    Open AI settings
                  </Button>
                </EmptyContent>
              ) : null}
            </Empty>
          </div>
        ) : (
          thread.messages.filter(message => message.role !== "tool" && message.content).map(message => (
            <div key={message.id} className="shrink-0">
              <AiConversationMessage
                messageId={message.id}
                role={message.role === "user" ? "user" : "assistant"}
                content={message.content}
                isAnimating={message.id === streamingAssistantId}
              />
            </div>
          ))
        )}
        <AiCurrentStep label={progressLabel} />
        <AiQuotaWarning enabled={aiSettings.configured} refreshKey={sending} />
        </AiQuotaScope>
      </AiTranscriptScroll>
      <AiChatComposer
        key={thread?.id ?? `map-${mapId ?? "none"}`}
        value={input}
        disabled={sending || loadingChats || !mapId || !aiSettings.configured}
        error={loadError}
        onChange={setInput}
        onSubmit={send}
      />
    </div>
  )
}
