import { getAdminParams } from "@/lib/admin-params"

type Flight = { family: string; promise: Promise<unknown> }
const flights = new Map<string, Flight>()

/** Requests may share work only within the same site's authenticated bootstrap. */
export function adminReadContext(): string {
  const params = getAdminParams()
  return JSON.stringify([params.apiUrl, params.homeUrl, params.user?.id, params.nonce])
}

/** Pending parsed reads only: success and failure both permit a fresh later read. */
export function singleFlightAdminRead<T>(family: string, url: string, read: () => Promise<T>): Promise<T> {
  const key = JSON.stringify([adminReadContext(), family, url])
  const pending = flights.get(key)
  if (pending) return pending.promise as Promise<T>
  const promise = Promise.resolve().then(read)
  const flight = { family, promise }
  flights.set(key, flight)
  const release = () => { if (flights.get(key) === flight) flights.delete(key) }
  // A detached finally() would create an unhandled rejected promise on failure.
  void promise.then(release, release)
  return promise
}

/** New reads after a write must not join a response started before that write. */
export function invalidateAdminReadFlights(family: string): void {
  for (const [key, flight] of flights) if (flight.family === family) flights.delete(key)
}
