import type { SvgRegionTarget } from './svg-regions'
/** Serialize distinct proposals in one turn; a failed save stops later writes. */
export function createSvgRegionQueue(apply:(target:SvgRegionTarget)=>Promise<{count:number}>) {
  const jobs=new Map<string,Promise<{count:number}>>()
  let tail:Promise<unknown>=Promise.resolve()
  return (target:SvgRegionTarget)=>{
    const key=`${target.mapId}:${target.draftId}:${target.analysisId}`
    const existing=jobs.get(key);if(existing)return existing
    const job=tail.then(()=>apply(target));jobs.set(key,job);tail=job
    void job.catch(()=>{}) // caller handles the result; preserve rejection for later jobs.
    return job
  }
}
