import { FileCode2Icon, FileSpreadsheetIcon, XIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import type { AiAttachment } from "../../lib/ai-attachments"

type Props = {
  attachments: AiAttachment[]
  onRemove?: (index: number) => void
  compact?: boolean
}

export function AiAttachmentTiles({
  attachments,
  onRemove,
  compact = false,
}: Props) {
  if (attachments.length === 0) return null

  return (
    <div className="flex flex-wrap gap-2">
      {attachments.map((attachment, index) => (
        <div
          key={`${attachment.kind}:${attachment.url}:${index}`}
          className="group/attachment relative overflow-hidden rounded-xl border bg-muted/30"
        >
          <a
            href={attachment.kind === "csv" ? undefined : attachment.url}
            target="_blank"
            rel="noreferrer"
            className="block"
            title={attachment.name}
          >
            <div
              className={
                compact
                  ? "flex h-14 w-16 items-center justify-center bg-background"
                  : "flex h-20 w-24 items-center justify-center bg-background"
              }
            >
              {attachment.kind === "csv" ? (
                <FileSpreadsheetIcon className="size-6 text-muted-foreground" />
              ) : attachment.url ? (
                <img
                  src={attachment.url}
                  alt=""
                  className="size-full object-contain"
                />
              ) : (
                <FileCode2Icon className="size-5 text-muted-foreground" />
              )}
            </div>
            <div className="max-w-24 truncate px-2 py-1 text-[11px] text-muted-foreground">
              {attachment.name}
            </div>
          </a>
          {onRemove ? (
            <Button
              type="button"
              variant="secondary"
              size="icon"
              className="absolute top-1 right-1 size-5 rounded-full opacity-0 shadow-sm transition-opacity group-hover/attachment:opacity-100"
              aria-label={`Remove ${attachment.name}`}
              onClick={() => onRemove(index)}
            >
              <XIcon className="size-3" />
            </Button>
          ) : null}
        </div>
      ))}
    </div>
  )
}
