import { ArrowDownIcon } from "lucide-react"
import {
  useCallback,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from "react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

type Props = {
  children: ReactNode
  scrollKey: string
  className?: string
  contentClassName?: string
}

const BOTTOM_THRESHOLD_PX = 48

export function AiTranscriptScroll({
  children,
  scrollKey,
  className,
  contentClassName,
}: Props) {
  const viewportRef = useRef<HTMLDivElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)
  const pinnedToBottomRef = useRef(true)
  const [showScrollButton, setShowScrollButton] = useState(false)
  const syncPinnedState = useCallback(() => {
    const viewport = viewportRef.current
    if (!viewport) return
    const distance =
      viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight
    const pinned = distance <= BOTTOM_THRESHOLD_PX
    pinnedToBottomRef.current = pinned
    setShowScrollButton(!pinned)
  }, [])

  const keepPinnedToBottom = useCallback(() => {
    const viewport = viewportRef.current
    if (!viewport || !pinnedToBottomRef.current) return
    viewport.scrollTop = viewport.scrollHeight
    setShowScrollButton(false)
  }, [])

  useLayoutEffect(keepPinnedToBottom, [scrollKey, keepPinnedToBottom])

  useLayoutEffect(() => {
    const viewport = viewportRef.current
    const content = contentRef.current
    if (!viewport || !content) return
    const observer = new ResizeObserver(keepPinnedToBottom)
    // The measured composer changes this element's padding, not just its content box.
    observer.observe(content, { box: "border-box" })
    observer.observe(viewport)
    return () => observer.disconnect()
  }, [keepPinnedToBottom])

  const scrollToBottom = () => {
    const viewport = viewportRef.current
    if (!viewport) return
    pinnedToBottomRef.current = true
    viewport.scrollTo({ top: viewport.scrollHeight, behavior: "smooth" })
    setShowScrollButton(false)
  }

  return (
    <div className={cn("relative flex min-h-0 flex-1", className)}>
      <div
        ref={viewportRef}
        role="region"
        aria-label="Messages"
        tabIndex={0}
        className="size-full min-h-0 min-w-0 scroll-fade-b scrollbar-thin scrollbar-gutter-stable overflow-y-auto overscroll-contain"
        onScroll={syncPinnedState}
      >
        <div
          ref={contentRef}
          role="log"
          aria-relevant="additions"
          className={cn(
            "mx-auto flex h-max min-h-full w-full max-w-[816px] flex-col gap-4 px-6 pt-3 pb-[calc(var(--ai-chat-composer-height,4.75rem)+80px)]",
            contentClassName,
          )}
        >
          {children}
        </div>
      </div>

      {showScrollButton ? (
        <Button
          type="button"
          variant="secondary"
          size="icon"
          className="absolute bottom-4 left-1/2 size-8 -translate-x-1/2 rounded-full border bg-background shadow-sm"
          aria-label="Scroll to end"
          onClick={scrollToBottom}
        >
          <ArrowDownIcon className="size-4" />
        </Button>
      ) : null}
    </div>
  )
}
