import { draftRequest } from "@/lib/app-drafts"
import { requestPreparedSvg } from "@/lib/prepared-svg-actions"

export type SvgRegionTarget = { analysisId: string; mapId: number; draftId: number }
export function regionProposal(target: SvgRegionTarget, action = "get", extra: Record<string, unknown> = {}) {
  if (!/^[a-f0-9]{32}$/.test(target.analysisId) || !Number.isSafeInteger(target.mapId) || !Number.isSafeInteger(target.draftId)) throw new Error("Invalid region proposal")
  return draftRequest<any>(`/ai/maps/${target.mapId}/regions/${target.analysisId}`, "POST", { action, ...extra })
}

/** The same native Save and reviewed additive sync used by Draw; never publish. */
export async function applySvgRegionProposal(target: SvgRegionTarget): Promise<{ count: number }> {
  try {
    const result = await requestPreparedSvg({ mapId: target.mapId, draftId: target.draftId,
      prepare: () => regionProposal(target, "prepare"),
      complete: (pageId, stateId) => regionProposal(target, "complete", { pageId, stateId }) })
    if (!result.ok) throw new Error(result.message)
    return { count: result.count }
  } catch (error) {
    await regionProposal(target, "failed").catch(() => {})
    throw error
  }
}
