export const AI_PUBLISH_REQUEST = "mapsvg:ai-publish-request"

/** Bound to the App/draft selected when the AI turn started, not when it ended. */
export type AiPublishTarget = { mapId: number; draftId: number }
export type AiPublishResult = { status: "completed"; versionId: number } | { status: "rejected" | "failed"; message?: string }
export type AiPublishRequest = AiPublishTarget & { respond: (result: AiPublishResult) => void }

/** App publishes its canonical draft and reports the acknowledged result. */
export function requestAiPublish(target: AiPublishTarget): Promise<AiPublishResult> {
  if (!Number.isSafeInteger(target.mapId) || target.mapId <= 0 || !Number.isSafeInteger(target.draftId) || target.draftId <= 0) return Promise.resolve({ status: "rejected" })
  return new Promise(resolve => {
    const event = new CustomEvent<AiPublishRequest>(AI_PUBLISH_REQUEST, { detail: { ...target, respond: resolve }, cancelable: true })
    if (window.dispatchEvent(event)) resolve({ status: "rejected" })
  })
}
