import type { AiTaskPlan } from "./ai-api"
import type { AiToolStage } from "./ai-tool-messages"

type Message = { role: string; content: string }

/** Live state only: never revive a saved plan/tool from an earlier human turn. */
export function currentAiStep(
  plan: AiTaskPlan | null | undefined,
  messages: readonly (Message & { id: string; stage?: AiToolStage })[],
  status: string | null,
): string | null {
  if (!status) return null
  let userIndex = messages.length - 1
  while (userIndex >= 0 && messages[userIndex].role !== "user") userIndex--
  if (userIndex < 0) return status
  if (plan?.running && plan.userMessageId === messages[userIndex].id) {
    const step = plan.steps.find(step => step.status === "in_progress")
    if (step?.title.trim()) return step.title
  }
  for (let index = messages.length - 1; index > userIndex; index--) {
    const message = messages[index]
    if (message.role === "tool" && message.stage === "tool_running") return message.content
  }
  return status
}

/** Only human prose selects the activity label's language; generated history and attached data do not. */
export function initialAiStatus(prompt: string, history: readonly Message[] = []): string {
  for (const message of [{ role: "user", content: prompt }, ...history.slice().reverse()]) {
    if (message.role !== "user") continue
    const prose = message.content
      .replace(/^Attachments:\s*$[\s\S]*/m, "")
      .replace(/```[\s\S]*?(?:```|$)|`[^`]*`/g, "")
      .replace(/^\s*>.*$/gm, "")
      .replace(/https?:\/\/\S+/g, "")
      .replace(/"[^"\n]*"|«[^»]*»/g, "")
    const russian = prose.match(/[а-яё]/gi)?.length ?? 0
    const letters = prose.match(new RegExp("\\p{L}", "gu"))?.length ?? 0
    if (letters) return russian > letters / 2 ? "Думаю" : "Thinking"
  }
  return "Thinking"
}
