import { UploadIcon } from "lucide-react"
import { useRef, useState } from "react"
import { MapFileGallery } from "@/components/MapFileGallery"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import type { ReactAdminSvgFileItem } from "@/lib/admin-params"
import { useAdminCatalog } from "@/lib/use-admin-catalog"
import { uploadSvgFile } from "../../lib/ai-attachments"

type Props = {
  open: boolean
  files: ReactAdminSvgFileItem[]
  onOpenChange: (open: boolean) => void
  onSelect: (file: ReactAdminSvgFileItem) => void
  onUploaded: (file: ReactAdminSvgFileItem) => void
}

export function AiSvgFilePicker({ open, files, onOpenChange, onSelect, onUploaded }: Props) {
  const [query, setQuery] = useState("")
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const catalog = useAdminCatalog("svg", open, files)
  const choose = (file: ReactAdminSvgFileItem) => {
    onSelect(file)
    onOpenChange(false)
  }
  const upload = async (file: File | undefined) => {
    if (!file || uploading) return
    setUploading(true)
    setError(null)
    try {
      const created = await uploadSvgFile(file)
      onUploaded(created)
      onSelect(created)
      onOpenChange(false)
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err))
    } finally {
      setUploading(false)
      if (inputRef.current) inputRef.current.value = ""
    }
  }

  return (
    <Dialog modal={false} open={open} onOpenChange={onOpenChange}>
      <DialogContent className="!flex h-[82vh] min-h-0 max-w-4xl flex-col gap-4 overflow-hidden">
        <DialogHeader className="shrink-0">
          <DialogTitle>SVG files</DialogTitle>
          <DialogDescription>Choose an existing MapSVG file or upload a new SVG.</DialogDescription>
        </DialogHeader>
        <input
          ref={inputRef}
          type="file"
          accept=".svg,image/svg+xml"
          className="hidden"
          onChange={(event) => void upload(event.target.files?.[0])}
        />
        {error ? (
          <div className="shrink-0 rounded-lg border border-destructive/30 px-3 py-2 text-sm text-destructive">
            {error}
          </div>
        ) : null}
        {catalog.loading ? <p role="status" className="text-sm text-muted-foreground">Loading files…</p> : null}
        {catalog.error ? <div role="alert" className="text-sm text-destructive">{catalog.error} <Button type="button" variant="link" onClick={catalog.retry}>Retry</Button></div> : null}
        <MapFileGallery
          files={catalog.files}
          label="SVG files"
          query={query}
          onQueryChange={setQuery}
          onSelect={choose}
          disabled={catalog.loading || Boolean(catalog.error)}
          actions={
            <Button
              type="button"
              variant="outline"
              disabled={uploading}
              onClick={() => inputRef.current?.click()}
            >
              <UploadIcon className="size-4" />
              {uploading ? "Uploading…" : "Upload SVG"}
            </Button>
          }
        />
      </DialogContent>
    </Dialog>
  )
}
