import {notifyProjectChat} from "@/lib/project-chats"
import { getAdminParams } from "@/lib/admin-params"
import { invalidateAdminReadFlights, singleFlightAdminRead } from "@/lib/admin-read-flight"
import { aiApiUrl } from "./ai-api-url"

export type AiProvider = "openai" | "deepseek"

export type AiPublicSettings = {
  provider: AiProvider
  model: string
  openaiConfigured: boolean
  deepseekConfigured: boolean
  configured: boolean
}

export type AiChatMessage = {
  role: "system" | "user" | "assistant"
  content: string
}

function apiBase(): { base: string; nonce: string } {
  const p = getAdminParams()
  return { base: p.apiUrl, nonce: p.nonce }
}

async function apiJson<T>(
  method: string,
  path: string,
  body?: unknown,
): Promise<T> {
  const { base, nonce } = apiBase()
  const rel = path.startsWith("/") ? path : `/${path}`
  const url = aiApiUrl(base, rel)
  const chats = /^\/ai\/chats(?:[/?]|$)/.test(rel)
  const request = async (): Promise<T> => {
    const controller = chats && method === "GET" ? new AbortController() : null
    const timer = controller ? setTimeout(() => controller.abort(), 15000) : null
    try {
      const res = await fetch(url, {
        method,
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          "X-WP-Nonce": nonce,
        },
        credentials: "same-origin",
        cache: method === "GET" ? "no-store" : "default",
        ...(controller ? { signal: controller.signal } : {}),
        body: body === undefined ? undefined : JSON.stringify(body),
      })
      const data = (await res.json().catch(error => {
        if (controller?.signal.aborted) throw error
        return {}
      })) as T & { error?: string }
      if (!res.ok) {
        const msg =
          typeof data === "object" && data && "error" in data && data.error
            ? String(data.error)
            : `API ${res.status}: ${path}`
        throw new Error(msg)
      }
      return data
    } catch (error) {
      if (controller?.signal.aborted) throw new Error("The chat history took too long to load. Please retry.")
      throw error
    } finally { if (timer !== null) clearTimeout(timer) }
  }
  if (chats && method === "GET") return singleFlightAdminRead("ai-chats", url, request)
  if (chats) {
    invalidateAdminReadFlights("ai-chats")
    try { return await request() }
    finally { invalidateAdminReadFlights("ai-chats") }
  }
  return request()
}

export function getBootAiSettings(): AiPublicSettings {
  const raw = getAdminParams().ai
  if (!raw || typeof raw !== "object") {
    return {
      provider: "openai",
      model: "gpt-6-luna",
      openaiConfigured: false,
      deepseekConfigured: false,
      configured: false,
    }
  }
  const o = raw as Partial<AiPublicSettings>
  const provider = o.provider === "deepseek" ? "deepseek" : "openai"
  return {
    provider,
    model: typeof o.model === "string" && o.model ? o.model : provider === "deepseek" ? "deepseek-flash" : "gpt-6-luna",
    openaiConfigured: Boolean(o.openaiConfigured),
    deepseekConfigured: Boolean(o.deepseekConfigured),
    configured: Boolean(o.configured),
  }
}


export async function updateAiSettings(body: {
  provider?: AiProvider
  model?: string
}): Promise<AiPublicSettings> {
  return apiJson<AiPublicSettings>("PUT", "/ai/settings", body)
}

export type AiPersistedChatListItem = {
  id: number
  mapId: number | null
  title: string
  createdAt: string
  updatedAt: string
}

export type AiPersistedMessage = {
  id: string
  dbId?: number
  role: "user" | "assistant" | "tool"
  content: string
}

export type AiPersistedChat = AiPersistedChatListItem & {
  taskPlan?: AiTaskPlan | null
  messages: AiPersistedMessage[]
  hasMore?: boolean
  messageCount?: number
}

export type AiTaskPlan = {
  /** Display ownership only; never planner authority or an execution receipt. */
  userMessageId?: string
  regionProposal?: { id: string; mapId: number; draftId: number; status: string; expiresAt: number; labelPolicyVersion?: number; geometryPolicyVersion?: number; instruction?: string; selectionMode?: "all" | "numbered"; targetLabels?: string[] }
  id: string
  mode: "discussion" | "direct" | "planned" | null
  reason: string
  running: boolean
  steps: Array<{
    id: string
    title: string
    status: "pending" | "in_progress" | "completed" | "blocked"
    note: string
    phase?: "discovery" | "create" | "work" | "verify"
    checks: Array<{ description: string; kind: "discovery" | "configuration" | "data" | "browser" }>
  }>
}

export async function fetchAiChats(
  mapId: number | null = null,
): Promise<AiPersistedChatListItem[]> {
  const path = mapId == null ? "/ai/chats" : `/ai/chats?mapId=${mapId}`
  const data = await apiJson<{ items?: AiPersistedChatListItem[] }>(
    "GET",
    path,
  )
  return Array.isArray(data.items) ? data.items : []
}

export async function fetchAiChat(
  id: number,
  opts?: { limit?: number; beforeId?: number },
): Promise<AiPersistedChat> {
  const params = new URLSearchParams()
  if (opts?.limit) params.set("limit", String(opts.limit))
  if (opts?.beforeId) params.set("beforeId", String(opts.beforeId))
  const qs = params.toString()
  const data = await apiJson<{ chat: AiPersistedChat }>(
    "GET",
    `/ai/chats/${id}${qs ? `?${qs}` : ""}`,
  )
  return data.chat
}

export async function createAiChat(body: {
  mapId?: number | null
  fresh?: boolean
  title?: string
  messages?: AiPersistedMessage[]
}): Promise<AiPersistedChat> {
  const data = await apiJson<{ chat: AiPersistedChat }>("POST", "/ai/chats", body)
  notifyProjectChat(data.chat)
  return data.chat
}

export async function updateAiChat(
  id: number,
  body: {
    mapId?: number | null
    title?: string
    appendMessages?: AiPersistedMessage[]
  },
): Promise<AiPersistedChat> {
  const data = await apiJson<{ chat: AiPersistedChat }>(
    "PUT",
    `/ai/chats/${id}`,
    body,
  )
  notifyProjectChat(data.chat)
  return data.chat
}

export async function fetchProjectChats():Promise<AiPersistedChatListItem[]> {
 const items:AiPersistedChatListItem[]=[];let beforeId=0
 for(let page=0;page<100;page++){
  const data=await apiJson<{items:AiPersistedChatListItem[]}>("GET",`/ai/chats?scope=projects${beforeId?`&beforeId=${beforeId}`:""}`)
  items.push(...data.items);if(data.items.length<100)return items
  const next=data.items[data.items.length-1]!.id;if(next>=beforeId && beforeId>0)throw new Error("Invalid project pagination");beforeId=next
 }
 throw new Error("Too many projects to load")
}
