import { type AiPublicSettings } from "../../lib/ai-api"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

type Props = {
  settings: AiPublicSettings
  onSaved: (next: AiPublicSettings) => void
  className?: string
}

/** AI access is included with the activated MapSVG license. */
export function AiSettingsForm({ settings, className }: Props) {
  return (
    <div className={cn("grid max-w-md gap-3 text-left", className)}>
      <p className="text-sm text-muted-foreground">
        {settings.configured
          ? "AI chat uses the credits included with your MapSVG license."
          : "Activate your MapSVG license in Usage to use your included AI credits."}
      </p>
      <Button type="button" variant="outline" onClick={() => window.dispatchEvent(new Event("mapsvg:open-usage"))}>
        {settings.configured ? "View AI credits" : "Activate AI"}
      </Button>
    </div>
  )
}
