export type AiToolStage = "tool_running" | "tool_done" | "tool_error" | "options_patch"

/** Keep the existing receipt/persistence boundary independent of chat presentation. */
const QUIET_AI_TOOLS = new Set([
  "plan_task",
  "update_task_plan",
  "revise_task_plan",
  "get_doc",
  "list_docs",
  "get_map_options",
  "apply_map_options_patch",
  "manage_options",
])

export function isQuietAiTool(name: string): boolean {
  return QUIET_AI_TOOLS.has(name.trim().toLowerCase())
}

export function isQuietAiToolMessage(content: string): boolean {
  const text = content.trim()
  if (/updated map options/i.test(text)) return false
  const match = text.match(/^(?:→\s*)?(?:ran|calling|failed)\s+([a-z0-9_]+)\b/i)
  return Boolean(match?.[1] && isQuietAiTool(match[1]))
}
