import {
  FileCode2Icon,
  ImageIcon,
  FileSpreadsheetIcon,
} from "lucide-react"
import {
  useEffect,
  useRef,
  useState,
  type FormEvent,
} from "react"
import { DropdownMenuItem } from "@/components/ui/dropdown-menu"
import { ChatComposer } from "@/components/ChatComposer"
import { useUpgradeReloadGuard } from "@/lib/upgrade-reload"
import { getAdminParams, type ReactAdminSvgFileItem } from "@/lib/admin-params"
import {
  absoluteAssetUrl,
  getBootSvgFiles,
  svgFileToAttachment,
  uploadCsvFile,
  uploadImageFile,
  type AiAttachment,
} from "../../lib/ai-attachments"
import { AiAttachmentTiles } from "./AiAttachmentTiles"
import { AiSvgFilePicker } from "./AiSvgFilePicker"

type Props = {
  value: string
  disabled?: boolean
  error?: string | null
  onChange: (value: string) => void
  onSubmit: (attachments: AiAttachment[]) => void | Promise<void>
}

type WpMediaAttachment = {
  url?: string
  filename?: string
  title?: string
  type?: string
  mime?: string
}

export function AiChatComposer({
  value,
  disabled = false,
  error = null,
  onChange,
  onSubmit,
}: Props) {
  const mediaHandlerRef = useRef<(() => void) | null>(null)
  const imageInputRef = useRef<HTMLInputElement>(null)
  const dropHostRef = useRef<HTMLDivElement>(null)
  const csvInputRef = useRef<HTMLInputElement>(null)
  const uploadRequestRef = useRef<AbortController | null>(null)
  const [uploading, setUploading] = useState(false)
  const [attachments, setAttachments] = useState<AiAttachment[]>([])
  const [svgFiles, setSvgFiles] = useState<ReactAdminSvgFileItem[]>(() =>
    getBootSvgFiles(),
  )
  const [svgPickerOpen, setSvgPickerOpen] = useState(false)
  const [attachmentError, setAttachmentError] = useState<string | null>(null)
  useUpgradeReloadGuard(uploading || attachments.length > 0, "Send or remove your unsent chat attachments before reloading the editor.")

  useEffect(() => {
    return () => {
      uploadRequestRef.current?.abort()
      const uploader = (window as any).mapsvg?.mediaUploader
      if (uploader && mediaHandlerRef.current) {
        uploader.off("select", mediaHandlerRef.current)
      }
    }
  }, [])
  const addAttachments = (items: AiAttachment[]) => {
    setAttachments((current) => {
      const urls = new Set(current.map((item) => item.url))
      return [
        ...current,
        ...items.filter((item) => item.url && !urls.has(item.url)),
      ]
    })
  }
  const chooseWpMedia = () => {
    setAttachmentError(null)
    const uploader =
      (window as any).mapsvg?.mediaUploader ??
      (window as any).MapSVG?.mediaUploader
    if (!uploader) {
      setAttachmentError("WordPress Media Library is unavailable.")
      return
    }

    if (mediaHandlerRef.current) {
      uploader.off("select", mediaHandlerRef.current)
    }

    const handler = () => {
      const state = uploader.state?.()
      const selected =
        state?.get?.("selection")?.toJSON?.() as WpMediaAttachment[] | undefined
      const images = (selected ?? [])
        .filter((item) => item.type === "image" || item.mime?.startsWith("image/"))
        .map((item) => ({
          kind: "image" as const,
          name: item.filename || item.title || "Image",
          url: absoluteAssetUrl(item.url || ""),
        }))
      addAttachments(images)
      uploader.off("select", handler)
      mediaHandlerRef.current = null
    }
    mediaHandlerRef.current = handler
    uploader.on("select", handler)
    uploader.open()
    const selection = uploader.state?.()?.get?.("selection")
    selection?.reset?.()
  }

  const submit = (event?: FormEvent) => {
    event?.preventDefault()
    if (disabled || uploading || (!value.trim() && attachments.length === 0)) return
    const selectedAttachments = attachments
    setAttachments([])
    void onSubmit(selectedAttachments)
  }

  const removeAttachment = (index: number) => {
    setAttachments((current) => current.filter((_, i) => i !== index))
  }
  const addSvgFile = (file: ReactAdminSvgFileItem) => {
    addAttachments([svgFileToAttachment(file)])
  }

  const addUploadedSvgFile = (file: ReactAdminSvgFileItem) => {
    setSvgFiles((current) => {
      if (current.some((item) => item.relativeUrl === file.relativeUrl)) {
        return current
      }
      return [file, ...current]
    })
  }

  const visibleError = attachmentError || error
  const chooseFiles = async (files: File[]) => {
    if (disabled || uploadRequestRef.current || !files.length) return
    const request = new AbortController()
    uploadRequestRef.current = request
    setUploading(true)
    setAttachmentError(null)
    try {
      for (const file of files) {
        if (request.signal.aborted) break
        const attachment = await (/\.csv$/i.test(file.name) ? uploadCsvFile(file, request.signal) : uploadImageFile(file, request.signal))
        if (!request.signal.aborted) addAttachments([attachment])
      }
    } catch (failure) {
      if (!request.signal.aborted) setAttachmentError(failure instanceof Error ? failure.message : "Could not upload attachment.")
    } finally {
      if (uploadRequestRef.current === request && !request.signal.aborted) {
        uploadRequestRef.current = null
        setUploading(false)
      }
    }
  }

  useEffect(() => {
    const host = dropHostRef.current?.closest("[data-ai-chat-overlay]")
    if (!host) return
    const drag = (event: Event) => {
      const data = (event as DragEvent).dataTransfer
      if (Array.from(data?.types ?? []).includes("Files")) event.preventDefault()
    }
    const drop = (event: Event) => {
      const files = Array.from((event as DragEvent).dataTransfer?.files ?? [])
      if (files.length) { event.preventDefault(); void chooseFiles(files) }
    }
    const paste = (event: Event) => {
      const files = Array.from((event as ClipboardEvent).clipboardData?.files ?? [])
      if (files.length) { event.preventDefault(); void chooseFiles(files) }
    }
    host.addEventListener("dragover", drag)
    host.addEventListener("drop", drop)
    host.addEventListener("paste", paste)
    return () => { host.removeEventListener("dragover", drag); host.removeEventListener("drop", drop); host.removeEventListener("paste", paste) }
  }, [disabled])

  return (
    <div className="contents" ref={dropHostRef}>
      <input ref={imageInputRef} type="file" accept=".svg,.png,.jpeg,.jpg,.webp,.gif,image/svg+xml,image/png,image/jpeg,image/webp,image/gif" multiple hidden aria-label="Attach image file"
        onChange={(event) => { const files = Array.from(event.currentTarget.files ?? []); event.currentTarget.value = ""; void chooseFiles(files) }} />
      <input ref={csvInputRef} type="file" accept=".csv,text/csv" hidden aria-label="Attach CSV file"
        onChange={(event) => { const file = event.currentTarget.files?.[0]; event.currentTarget.value = ""; if (file) void chooseFiles([file]) }} />
      {uploading ? <p className="mb-2 text-xs text-muted-foreground" role="status">Uploading attachment…</p> : null}
      <ChatComposer value={value} disabled={disabled || uploading} error={visibleError} onChange={onChange} onSubmit={submit}
        hasAttachments={attachments.length > 0}
        attachments={attachments.length > 0 ? <AiAttachmentTiles attachments={attachments} compact onRemove={removeAttachment} /> : null}
        attachmentMenu={<>
          <DropdownMenuItem className="cursor-pointer" onSelect={() => imageInputRef.current?.click()}>
            <ImageIcon className="size-4" />Image file
          </DropdownMenuItem>
          <DropdownMenuItem className="cursor-pointer" disabled={!getAdminParams().databaseImportEnabled} onSelect={() => csvInputRef.current?.click()}>
            <FileSpreadsheetIcon className="size-4" />CSV file
          </DropdownMenuItem>
          <DropdownMenuItem className="cursor-pointer" onSelect={chooseWpMedia}>
            <ImageIcon className="size-4" />WP Media Library
          </DropdownMenuItem>
          <DropdownMenuItem className="cursor-pointer" onSelect={() => setSvgPickerOpen(true)}>
            <FileCode2Icon className="size-4" />SVG files
          </DropdownMenuItem>
        </>}
      />
      <AiSvgFilePicker
        open={svgPickerOpen}
        files={svgFiles}
        onOpenChange={setSvgPickerOpen}
        onSelect={addSvgFile}
        onUploaded={addUploadedSvgFile}
      />
    </div>
  )
}
