/** Append to the REST route while preserving pretty/plain permalink query arguments. */
export function resourceApiUrl(base: string, suffix = ""): string {
  if (!base || base.includes("#")) throw new Error("Invalid resource API baseUrl")
  const split = base.indexOf("?")
  const path = split < 0 ? base : base.slice(0, split)
  const search = split < 0 ? "" : base.slice(split + 1)
  const params = new URLSearchParams(search)
  if (params.has("rest_route")) {
    const route = params.get("rest_route")!
    if (params.getAll("rest_route").length !== 1 || !route.startsWith("/"))
      throw new Error("Invalid resource API rest_route")
    params.set("rest_route", route.replace(/\/+$/, "") + suffix)
    return path + "?" + params.toString()
  }
  return path.replace(/\/+$/, "") + suffix + (search ? "?" + search : "")
}
