import { getAdminParams, type ReactAdminSvgFileItem } from "@/lib/admin-params"
import { aiApiUrl } from "./ai-api-url"

export type AiAttachmentKind = "image" | "svg" | "csv"

export type AiAttachment = {
  kind: AiAttachmentKind
  name: string
  url: string
  attachmentId?: string
}

/** Direct MapSVG upload, using the same unique asset endpoints as manual creation. */
export async function uploadImageFile(file: File, signal?: AbortSignal): Promise<AiAttachment> {
  const svg = /\.svg$/i.test(file.name)
  if (!/\.(svg|png|jpe?g|webp|gif)$/i.test(file.name) || !file.size || file.size > (svg ? 8 * 1024 * 1024 : 6000000)) {
    throw new Error("Choose SVG (up to 8 MB), PNG, JPEG, WebP or GIF (up to 6 MB).")
  }
  const { apiUrl, nonce } = getAdminParams()
  const form = new FormData()
  form.append("file", svg ? new Blob([file], { type: "image/svg+xml" }) : file, file.name)
  if (svg) form.append("createNew", "true")
  const response = await fetch(aiApiUrl(apiUrl, `/${svg ? "svgfile" : "imagefile"}`), {
    method: "POST", headers: { "X-WP-Nonce": nonce }, credentials: "same-origin", body: form, signal,
  })
  const data = await response.json().catch(() => ({})) as { file?: { name?: string; relativeUrl?: string }; error?: string; message?: string }
  if (!response.ok || !data.file?.relativeUrl) throw new Error(data.error || data.message || `Image upload failed (${response.status}).`)
  return { kind: svg ? "svg" : "image", name: data.file.name || file.name, url: absoluteAssetUrl(data.file.relativeUrl) }
}

const ATTACHMENT_TITLE_PREFIX = "mapsvg-attachment:"

export function absoluteAssetUrl(url: string): string {
  if (!url) return ""
  try {
    return new URL(url, getAdminParams().homeUrl || window.location.origin).href
  } catch {
    return url
  }
}

export function getBootSvgFiles(): ReactAdminSvgFileItem[] {
  return getAdminParams().svgFiles
}
export function svgFileToAttachment(file: ReactAdminSvgFileItem): AiAttachment {
  return {
    kind: "svg",
    name: file.name || file.pathShort || "SVG file",
    url: absoluteAssetUrl(file.relativeUrl),
  }
}

function safeMarkdownLabel(value: string): string {
  return (
    value.split("[").join(" ").split("]").join(" ").replace(/[\r\n]/g, " ").trim() ||
    "attachment"
  )
}

export function withAttachments(
  text: string,
  attachments: AiAttachment[],
): string {
  const body = text.trim()
  if (attachments.length === 0) return body

  const lines = attachments.map((attachment) => {
    const label = safeMarkdownLabel(attachment.name)
    const url = absoluteAssetUrl(attachment.url)
    return `[${label}](<${url}> "${ATTACHMENT_TITLE_PREFIX}${attachment.kind}")`
  })
  return [body, "Attachments:", ...lines].filter(Boolean).join("\n\n")
}
export function parseAttachmentMessage(content: string): {
  text: string
  attachments: AiAttachment[]
} {
  const lines = content.split(/\r?\n/)
  const attachments: AiAttachment[] = []
  const kept: string[] = []

  const pattern =
    /^\[([^\]]+)\]\(<([^>]+)> "mapsvg-attachment:(image|svg|csv)"\)$/

  for (const line of lines) {
    const match = line.match(pattern)
    if (!match) {
      kept.push(line)
      continue
    }
    attachments.push({
      name: match[1] || "attachment",
      url: match[2] || "",
      kind: match[3] as AiAttachmentKind,
    })
  }

  if (attachments.length > 0) {
    while (kept.length && kept[kept.length - 1]?.trim() === "") kept.pop()
    if (kept[kept.length - 1]?.trim() === "Attachments:") kept.pop()
  }

  return { text: kept.join("\n").trim(), attachments }
}
export async function uploadCsvFile(file: File, signal?: AbortSignal): Promise<AiAttachment> {
  if (!/\.csv$/i.test(file.name) || file.size === 0 || file.size > 2 * 1024 * 1024) {
    throw new Error("Choose a non-empty CSV file up to 2 MB.")
  }
  const { apiUrl, nonce } = getAdminParams()
  const form = new FormData()
  form.append("file", file, file.name)
  const response = await fetch(aiApiUrl(apiUrl, "/ai/attachments/csv"), {
    method: "POST", headers: { "X-WP-Nonce": nonce }, credentials: "same-origin", body: form, signal,
  })
  const data = await response.json().catch(() => ({})) as { attachment?: AiAttachment; message?: string; error?: string }
  if (!response.ok || data.attachment?.kind !== "csv" || !data.attachment.attachmentId) {
    throw new Error(data.message || data.error || `CSV upload failed (${response.status}).`)
  }
  return data.attachment
}
export async function uploadSvgFile(
  file: File,
): Promise<ReactAdminSvgFileItem> {
  if (!/\.svg$/i.test(file.name)) {
    throw new Error("Only SVG files can be uploaded.")
  }

  const { apiUrl, nonce } = getAdminParams()
  const form = new FormData()
  form.append("file", file, file.name)

  const response = await fetch(aiApiUrl(apiUrl, "/svgfile"), {
    method: "POST",
    headers: { "X-WP-Nonce": nonce },
    credentials: "same-origin",
    body: form,
  })

  const data = (await response.json().catch(() => ({}))) as {
    file?: ReactAdminSvgFileItem
    error?: string
  }
  if (!response.ok || !data.file) {
    throw new Error(data.error || `SVG upload failed (${response.status}).`)
  }
  return data.file
}
