import { Bubble, BubbleContent } from "@/components/ui/bubble"
import { Message, MessageContent } from "@/components/ui/message"
import { aiDisplayText } from "../../lib/ai-display-text"
import { parseAttachmentMessage } from "../../lib/ai-attachments"
import { AiAttachmentTiles } from "./AiAttachmentTiles"
import { AiQuotaError, QUOTA_ERROR_PREFIX } from "./AiQuotaNotice"
import { ChatMarkdown } from "./ChatMarkdown"

type Props = {
  role: "user" | "assistant"
  content: string
  messageId?: string
  isAnimating?: boolean
}

export function AiConversationMessage({ role, content, messageId, isAnimating = false }: Props) {
  const user = role === "user"
  const align = user ? "end" : "start"
  const parsed = user
    ? parseAttachmentMessage(content)
    : {
        text:
          aiDisplayText(content) ||
          (content ? "The AI returned an invalid response. Please try again." : ""),
        attachments: [],
      }

  const quotaErrorAt = !user ? parsed.text.indexOf(QUOTA_ERROR_PREFIX) : -1
  const text = quotaErrorAt >= 0 ? parsed.text.slice(0, quotaErrorAt).trim() : parsed.text
  return (
    <Message align={align}>
      <MessageContent>
        <Bubble
          variant={user ? "default" : "ghost"}
          align={align}
          className={user ? undefined : "w-full max-w-full"}
        >
          <BubbleContent className={user ? "flex flex-col gap-2 text-sm" : "w-full text-sm"}>
            {parsed.attachments.length > 0 ? (
              <AiAttachmentTiles attachments={parsed.attachments} />
            ) : null}
            {text ? <ChatMarkdown isAnimating={isAnimating}>{text}</ChatMarkdown> : null}
            {quotaErrorAt >= 0 ? (
              <AiQuotaError key={messageId ?? content} messageId={messageId} />
            ) : null}
          </BubbleContent>
        </Bubble>
      </MessageContent>
    </Message>
  )
}
