import { getAppDraftSession } from "./app-drafts"
import { getAdminMapInstance } from "./apply-options-patch"

export type AiDraftState = {
  mapId: number; draftId: number; revision: number; dirty: boolean; localSaved: boolean
  conflicted: boolean; offline: boolean; ready: boolean; busy: boolean; transitioning: boolean
}
export function getAiDraftState(mapId: number | null): AiDraftState | null {
  if (!mapId || getAdminMapInstance()?.id !== mapId) return null
  const session = getAppDraftSession(mapId), copy = session.active
  if (!session.ready || !copy) return null
  return { mapId, draftId: copy.draft.id, revision: copy.revision, dirty: copy.dirty, localSaved: copy.localSaved,
    conflicted: copy.conflicted, offline: session.offline, ready: session.ready, busy: session.busy, transitioning: session.transitioning }
}

export const AI_DRAFT_ACTION_REQUEST = "mapsvg:ai-draft-action-request"
export type AiDraftAction = "pull_changes" | "branch"
export type AiDraftActionResult = { status: "confirmation_required" | "completed" | "rejected" | "failed"; draftId?: number }
export type AiDraftActionRequest = {
  mapId: number; draftId: number; action: AiDraftAction; respond: (result: AiDraftActionResult) => void
}

/** The App owns confirmation, canonical snapshots, writes and action completion. */
export function requestAiDraftAction(target: Omit<AiDraftActionRequest, "respond">): Promise<AiDraftActionResult> {
  if (!Number.isSafeInteger(target.mapId) || target.mapId <= 0 || !Number.isSafeInteger(target.draftId) || target.draftId <= 0
    || !["pull_changes", "branch"].includes(target.action)) return Promise.resolve({ status: "rejected" })
  return new Promise(resolve => {
    const event = new CustomEvent<AiDraftActionRequest>(AI_DRAFT_ACTION_REQUEST, { detail: { ...target, respond: resolve }, cancelable: true })
    if (window.dispatchEvent(event)) resolve({ status: "rejected" })
  })
}
