import { CheckIcon, CopyIcon } from "lucide-react"
import { isValidElement, useEffect, useMemo, useState, type ReactNode } from "react"
import ReactMarkdown, { defaultUrlTransform, type Components } from "react-markdown"
import remarkGfm from "remark-gfm"
import remend from "remend"
import hljs from "highlight.js/lib/core"
import css from "highlight.js/lib/languages/css"
import handlebars from "highlight.js/lib/languages/handlebars"
import javascript from "highlight.js/lib/languages/javascript"
import php from "highlight.js/lib/languages/php"
import xml from "highlight.js/lib/languages/xml"
import "highlight.js/styles/github-dark.css"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

hljs.registerLanguage("css", css)
hljs.registerLanguage("handlebars", handlebars)
hljs.registerLanguage("javascript", javascript)
hljs.registerLanguage("php", php)
hljs.registerLanguage("xml", xml)

function nodeText(node: ReactNode): string {
  if (node == null || typeof node === "boolean") return ""
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(nodeText).join("")
  if (isValidElement<{ children?: ReactNode }>(node)) {
    return nodeText(node.props.children)
  }
  return ""
}

function escapeHtml(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
}

function highlight(code: string, language?: string): string {
  const trimmed = code.replace(/\n$/, "")
  try {
    if (language && hljs.getLanguage(language)) {
      return hljs.highlight(trimmed, { language }).value
    }
    return hljs.highlightAuto(trimmed).value
  } catch {
    return escapeHtml(trimmed)
  }
}

function CodeBlock({
  code,
  language,
  className,
}: {
  code: string
  language?: string
  className?: string
}) {
  const [copied, setCopied] = useState(false)

  useEffect(() => {
    if (!copied) return
    const id = window.setTimeout(() => setCopied(false), 1500)
    return () => window.clearTimeout(id)
  }, [copied])

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(code.replace(/\n$/, ""))
      setCopied(true)
    } catch {
      setCopied(false)
    }
  }

  return (
    <div className="my-2 overflow-hidden rounded-md border border-border" data-mapsvg-ai-code-block>
      <div className="flex items-center justify-between gap-2 border-b border-border bg-zinc-900 px-[15px] py-1.5">
        <span className="font-mono text-[11px] text-zinc-400 lowercase">{language || "code"}</span>
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              type="button"
              aria-label={copied ? "Copied" : "Copy code"}
              className="rounded-md p-1 text-zinc-400 transition-colors hover:bg-white/10 hover:text-zinc-100"
              onClick={() => void copy()}
            >
              {copied ? <CheckIcon className="size-3.5" /> : <CopyIcon className="size-3.5" />}
            </button>
          </TooltipTrigger>
          <TooltipContent side="top">{copied ? "Copied" : "Copy"}</TooltipContent>
        </Tooltip>
      </div>
      <pre className="m-0 overflow-x-auto bg-zinc-900 px-[15px] py-[10px] text-xs leading-relaxed">
        <code
          className={cn("hljs bg-transparent p-0 text-zinc-100", className)}
          dangerouslySetInnerHTML={{ __html: highlight(code, language) }}
        />
      </pre>
    </div>
  )
}

const markdownComponents: Components = {
  pre: ({ children }) => <>{children}</>,
  code: ({ className, children, ...props }) => {
    const text = nodeText(children)
    const langMatch = /language-([a-z0-9_+-]+)/i.exec(className ?? "")
    const language = langMatch?.[1]
    const isBlock = "data-block" in props || Boolean(language) || text.includes("\n")

    if (!isBlock) {
      return (
        <code
          className={cn("rounded bg-foreground/15 px-1 py-0.5 font-mono text-[0.85em]", className)}
        >
          {children}
        </code>
      )
    }

    return <CodeBlock code={text} language={language} className={className} />
  },
  p: ({ children }) => <p className="my-2 leading-relaxed">{children}</p>,
  ul: ({ children }) => <ul className="my-2 list-disc space-y-1 pl-5">{children}</ul>,
  ol: ({ children }) => <ol className="my-2 list-decimal space-y-1 pl-5">{children}</ol>,
  li: ({ children }) => <li className="pl-0.5">{children}</li>,
  blockquote: ({ children }) => (
    <blockquote className="my-2 border-l-2 border-border pl-3 text-muted-foreground">
      {children}
    </blockquote>
  ),
  h1: ({ children }) => <h1 className="mb-2 mt-4 text-lg font-semibold">{children}</h1>,
  h2: ({ children }) => <h2 className="mb-2 mt-4 text-base font-semibold">{children}</h2>,
  h3: ({ children }) => <h3 className="mb-1.5 mt-3 text-sm font-semibold">{children}</h3>,
  a: ({ href, children }) => {
    if (!href || href === "streamdown:incomplete-link") {
      return <span>{children}</span>
    }
    return (
      <a
        href={href}
        target="_blank"
        rel="noreferrer noopener"
        className="underline underline-offset-2"
      >
        {children}
      </a>
    )
  },
  hr: () => <hr className="my-3 border-border" />,
  table: ({ children }) => (
    <div className="my-2 overflow-x-auto">
      <table className="w-full border-collapse text-left text-xs">{children}</table>
    </div>
  ),
  th: ({ children }) => (
    <th className="border border-border bg-muted px-2 py-1.5 font-medium">{children}</th>
  ),
  td: ({ children }) => <td className="border border-border px-2 py-1.5">{children}</td>,
}

type Props = {
  children: string
  className?: string
  /** True while this message's text is still streaming in. */
  isAnimating?: boolean
}

/**
 * Streaming-friendly Markdown renderer.
 *
 * Raw HTML is intentionally not enabled. During streaming, Remend closes
 * incomplete Markdown delimiters before ReactMarkdown parses the text.
 */
export function ChatMarkdown({ children, className, isAnimating = false }: Props) {
  const markdown = useMemo(
    () =>
      isAnimating
        ? remend(children, {
            katex: false,
            inlineKatex: false,
          })
        : children,
    [children, isAnimating],
  )

  return (
    <div
      className={cn("size-full [&>*:first-child]:mt-0 [&>*:last-child]:mb-0", className)}
      data-mapsvg-ai-markdown
      data-streaming={isAnimating ? "true" : undefined}
    >
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        skipHtml
        components={markdownComponents}
        urlTransform={(url) =>
          url === "streamdown:incomplete-link" ? "" : defaultUrlTransform(url)
        }
      >
        {markdown}
      </ReactMarkdown>
    </div>
  )
}
