import { AiQuotaWarning, AiQuotaScope } from "./AiQuotaNotice"
import { useChatComposerDraft } from "@/lib/chat-composer-draft"
import { useUpgradeReloadGuard } from "@/lib/upgrade-reload"
import { getActiveWorkspaceTabId } from "@/lib/workspace-context"
import { useBootAiSettings } from "../../lib/use-ai-settings"
import {Button} from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import {notifyProjectChat} from "@/lib/project-chats"
import { useEffect, useMemo, useRef, useState } from "react"
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/components/ui/empty"
import type { AdminPanelProps } from "@/lib/admin-extension-registry"
import {
  createAiChat, fetchAiChat,
  updateAiChat,
  type AiChatMessage,
  type AiPersistedMessage,
} from "../../lib/ai-api"
import { streamAiChat } from "../../lib/stream-ai-chat"
import { currentAiStep, initialAiStatus } from "../../lib/ai-progress"
import {
  withAttachments,
  type AiAttachment,
} from "../../lib/ai-attachments"
import { AiChatComposer } from "./AiChatComposer"
import { AiConversationMessage } from "./AiConversationMessage"
import { AiCurrentStep } from "./AiCurrentStep"
import type { AiTaskPlan } from "../../lib/ai-api"
import {
  isQuietAiTool,
  isQuietAiToolMessage,
  type AiToolStage,
} from "../../lib/ai-tool-messages"
import { AiTranscriptScroll } from "./AiTranscriptScroll"

type StartMessage = {
  id: string
  dbId?:number
  role: "user" | "assistant" | "tool"
  content: string
  stage?: AiToolStage
}

const AI_CONTEXT_WINDOW_MESSAGES = 50

function persistedMessages(messages: AiPersistedMessage[]): StartMessage[] {
  return messages
    .filter(
      (message): message is AiPersistedMessage & {
        role: "user" | "assistant" | "tool"
      } =>
        message.role === "user" ||
        message.role === "assistant" ||
        (message.role === "tool" && !isQuietAiToolMessage(message.content)),
    )
    .map(({ id, role, content, dbId }) => ({
      id, dbId,
      role,
      content,
    }))
}

function messageId(prefix: string): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return `${prefix}-${crypto.randomUUID()}`
  }
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2)}`
}
export function AiStartScreen({ startScreenActions, chatId: initialChatId, onChatSaved }: AdminPanelProps) {
  const settings = useBootAiSettings()
  const [taskPlan, setTaskPlan] = useState<AiTaskPlan | null>(null)
  const [messages, setMessages] = useState<StartMessage[]>([])
  const [chatId, setChatId] = useState<number | null>(initialChatId ?? null)
  const loadedChatRef=useRef<number|null>(null)
  const [restoreFailure, setRestoreFailure] = useState<{ chatId: number; message: string } | null>(null)
  const [restoreAttempt, setRestoreAttempt] = useState(0)
  // Gate the very first render, before the history-fetch effect runs. A saved
  // chat is not an empty welcome screen while its transcript is still unknown.
  const needsHistory = initialChatId != null && loadedChatRef.current !== initialChatId
  const failedToRestore = needsHistory && restoreFailure?.chatId === initialChatId
  const restoring = needsHistory && !failedToRestore
  const [hasMore,setHasMore]=useState(false)
  const [loadingEarlier,setLoadingEarlier]=useState(false)
  const [input, setInput] = useChatComposerDraft(`project:${initialChatId ?? getActiveWorkspaceTabId() ?? "welcome"}`)
  const [busy, setBusy] = useState(false)
  useUpgradeReloadGuard(busy, "Wait for the current AI request to finish before reloading the editor.")
  const [statusText, setStatusText] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const streamingIdRef = useRef<string | null>(null)
  const workingMessagesRef = useRef<StartMessage[]>([])
  const requestRef = useRef<AbortController | null>(null)

  // A welcome screen is a new conversation, never an implicit history selection.
  useEffect(() => () => {
    const request = requestRef.current
    requestRef.current = null
    request?.abort()
  }, [])

  useEffect(()=>{
    if(!initialChatId || loadedChatRef.current===initialChatId || requestRef.current)return
    let retired=false;setRestoreFailure(null);setError(null)
    void fetchAiChat(initialChatId).then(saved=>{
      if(retired)return
      loadedChatRef.current=saved.id;setChatId(saved.id);setMessages(persistedMessages(saved.messages));setHasMore(Boolean(saved.hasMore));setTaskPlan(saved.taskPlan ?? null);onChatSaved?.(saved)
    }).catch(e=>{if(!retired)setRestoreFailure({chatId:initialChatId,message:e instanceof Error?e.message:String(e)})})
    return()=>{retired=true}
  },[initialChatId,restoreAttempt])

  const loadEarlier=async()=>{
    const id=chatId,beforeId=messages.find(m=>m.dbId!=null)?.dbId
    if(!id || !beforeId || loadingEarlier || busy)return
    setLoadingEarlier(true)
    try{const page=await fetchAiChat(id,{beforeId});if(loadedChatRef.current!==id)return
      setMessages(current=>[...persistedMessages(page.messages).filter(m=>!current.some(c=>c.id===m.id)),...current]);setHasMore(Boolean(page.hasMore))
    }catch(e){setError(e instanceof Error?e.message:String(e))}finally{setLoadingEarlier(false)}
  }

  const send = async (attachments: AiAttachment[] = []) => {
    const content = withAttachments(input.trim(), attachments)
    if (!content || busy || restoring || requestRef.current || !settings.configured) return
    const request = new AbortController()
    requestRef.current = request
    const current = () => requestRef.current === request && !request.signal.aborted

    const userMessage: StartMessage = {
      id: messageId("user"),
      role: "user",
      content,
    }
    const assistantMessage: StartMessage = {
      id: messageId("assistant"),
      role: "assistant",
      content: "",
    }
    const history = messages
      .filter((message) => message.role !== "tool")
      .slice(-AI_CONTEXT_WINDOW_MESSAGES)
    const requestMessages: AiChatMessage[] = [...history, userMessage].map((message) => ({
      role: message.role as "user" | "assistant",
      content: message.content,
    }))

    setInput("")
    setBusy(true)
    setStatusText(initialAiStatus(input.trim(), history))
    setError(null)
    streamingIdRef.current = assistantMessage.id
    workingMessagesRef.current = [...messages, userMessage, assistantMessage]
    setMessages(workingMessagesRef.current)

    let persistedChatId = chatId
    let pendingOpenMap: { mapId: number; title: string } | null = null
    const getPendingOpenMap = (): { mapId: number; title: string } | null => pendingOpenMap
    const completedToolMessages: StartMessage[] = []
    let streamCompleted = false
    let streamFailed = false

    const upsertWorkingMessage = (message: StartMessage) => {
      const index = workingMessagesRef.current.findIndex(
        (candidate) => candidate.id === message.id,
      )
      workingMessagesRef.current =
        index === -1
          ? [...workingMessagesRef.current, message]
          : workingMessagesRef.current.map((candidate, candidateIndex) =>
              candidateIndex === index ? message : candidate,
            )
      setMessages(workingMessagesRef.current)
    }

    try {
      if (persistedChatId == null) {
        const created = await createAiChat({
          mapId: null,
          fresh: true,
          title: "New project",
          messages: [
            {
              id: userMessage.id,
              role: userMessage.role,
              content: userMessage.content,
            },
          ],
        })
        persistedChatId = created.id
        if (!current()) return
        loadedChatRef.current=created.id
        setChatId(created.id)
        onChatSaved?.(created)
        const persisted = persistedMessages(created.messages)
        workingMessagesRef.current = [...messages.filter(m=>!persisted.some(p=>p.id===m.id)),...persisted, assistantMessage]
      } else {
        const saved = await updateAiChat(persistedChatId, {
          appendMessages: [
            {
              id: userMessage.id,
              role: userMessage.role,
              content: userMessage.content,
            },
          ],
        })
        if (!current()) return
        const persisted = persistedMessages(saved.messages)
        workingMessagesRef.current = [...messages.filter(m=>!persisted.some(p=>p.id===m.id)),...persisted, assistantMessage]
      }

      streamingIdRef.current = assistantMessage.id
      setMessages(workingMessagesRef.current)

      await streamAiChat({
        messages: requestMessages,
        chatId: persistedChatId,
        mapId: null,
        signal: request.signal,
        onEvent: (event) => {
          if (!current()) return
          if(event.type==="chat_title" && event.chatId===persistedChatId){
            notifyProjectChat({id:Number(event.chatId),mapId:typeof event.mapId==="number"?event.mapId:null,title:String(event.title),createdAt:"",updatedAt:new Date().toISOString()})
          } else if (event.type === "status" && typeof event.text === "string") {
            setStatusText(initialAiStatus(userMessage.content, history))
          } else if (event.type === "task_plan") {
            setTaskPlan({ ...(event.plan as AiTaskPlan), userMessageId: userMessage.id })
          } else if (event.type === "text_delta") {
            setStatusText(null)
            workingMessagesRef.current = workingMessagesRef.current.map((message) =>
              message.id === assistantMessage.id
                ? { ...message, content: message.content + event.text }
                : message,
            )
            setMessages(workingMessagesRef.current)
          } else if (event.type === "error") {
            streamFailed = true
            setStatusText(null)
            setError(typeof event.error === "string" ? event.error : String(event.error))
            workingMessagesRef.current = workingMessagesRef.current.map((message) =>
              message.id === assistantMessage.id
                ? {
                    ...message,
                    content: message.content
                      ? `${message.content}\n\nError: ${event.error}`
                      : `Error: ${event.error}`,
                  }
                : message,
            )
            setMessages(workingMessagesRef.current)
          } else if (event.type === "tool_call") {
            setStatusText(initialAiStatus(userMessage.content, history))
            const id = String(event.id || `tool-${Date.now()}`)
            const name = String(event.name || "tool")
            if (!isQuietAiTool(name)) {
              upsertWorkingMessage({
                id,
                role: "tool",
                stage: "tool_running",
                content: `Calling ${name}`,
              })
            }
          } else if (event.type === "tool_result") {
            const id = String(event.id || `tool-${Date.now()}`)
            const name = String(event.name || "tool")
            if (!isQuietAiTool(name)) {
              const ok = Boolean(event.ok)
              const err =
                typeof event.error === "string" && event.error
                  ? event.error
                  : null
              const message: StartMessage = {
                id,
                role: "tool",
                stage: ok ? "tool_done" : "tool_error",
                content: ok
                  ? `Ran ${name}`
                  : `Failed ${name}${err ? `: ${err}` : ""}`,
              }
              upsertWorkingMessage(message)
              const existing = completedToolMessages.findIndex(
                (candidate) => candidate.id === id,
              )
              if (existing === -1) {
                completedToolMessages.push(message)
              } else {
                completedToolMessages[existing] = message
              }
            }
          } else if (event.type === "done") {
            setStatusText(null)
          } else if (event.type === "map_mutation") {
            window.dispatchEvent(
              new CustomEvent("mapsvg:map-mutation", { detail: event }),
            )
          } else if (event.type === "schema_mutation") {
            window.dispatchEvent(
              new CustomEvent("mapsvg:schema-mutation", { detail: event }),
            )
          } else if (event.type === "repository_mutation") {
            window.dispatchEvent(
              new CustomEvent("mapsvg:repository-mutation", { detail: event }),
            )
          } else if (event.type === "query_mutation") {
            window.dispatchEvent(
              new CustomEvent("mapsvg:query-mutation", { detail: event }),
            )
          } else if (event.type === "connection_mutation") {
            window.dispatchEvent(
              new CustomEvent("mapsvg:connection-mutation", { detail: event }),
            )
          } else if (event.type === "global_settings_mutation") {
            window.dispatchEvent(
              new CustomEvent("mapsvg:global-settings-mutation", { detail: event }),
            )
          } else if (event.type === "open_map" && typeof event.mapId === "number") {
            pendingOpenMap = {
              mapId: event.mapId,
              title:
                typeof event.title === "string" && event.title
                  ? event.title
                  : `Map #${event.mapId}`,
            }
          }
        },
      })
      streamCompleted = true
    } catch (streamError) {
      streamFailed = true
      if (current()) {
        setStatusText(null)
        const message = streamError instanceof Error
          ? streamError.message : "Could not reach the MapSVG AI assistant."
        setError(message)
        workingMessagesRef.current = workingMessagesRef.current.map(candidate =>
          candidate.id === assistantMessage.id
            ? { ...candidate, content: `${candidate.content}${candidate.content ? "\n\n" : ""}Error: ${message}` }
            : candidate)
        setMessages(workingMessagesRef.current)
      }
    } finally {
      const finalAssistant = workingMessagesRef.current.find(
        (message) => message.id === assistantMessage.id,
      )
      if (persistedChatId != null) {
        const update: {
          mapId?: number
          appendMessages?: Array<{
            id: string
            role: "user" | "assistant" | "tool"
            content: string
          }>
        } = {}

        const openMap = getPendingOpenMap()
        if (openMap) {
          update.mapId = openMap.mapId
        }

        const appendMessages = completedToolMessages.map((message) => ({
          id: message.id,
          role: message.role,
          content: message.content,
        }))
        if (finalAssistant?.content.trim()) {
          appendMessages.push({
            id: finalAssistant.id,
            role: finalAssistant.role,
            content: finalAssistant.content,
          })
        }
        if (appendMessages.length > 0) {
          update.appendMessages = appendMessages
        }

        if (update.mapId != null || update.appendMessages) {
          try {
            await updateAiChat(persistedChatId, update)
          } catch (err) {
            if (current()) setError(err instanceof Error ? err.message : String(err))
          }
        }
      }

      const finishedMap=getPendingOpenMap()
      if (current() && finishedMap && streamCompleted && !streamFailed) {
        window.dispatchEvent(
          new CustomEvent("mapsvg:open-map", { detail: {...finishedMap,chatId:persistedChatId} }),
        )
      }

      if (current()) {
        requestRef.current = null
        streamingIdRef.current = null
        workingMessagesRef.current = []
        setStatusText(null)
        setBusy(false)
      }
    }
  }

  const showIntro = messages.length === 0
  const progressLabel = busy ? currentAiStep(taskPlan, messages, statusText) : null
  const transcriptScrollKey = useMemo(
    () =>
      `${messages.map(message => `${message.id}:${message.content.length}`).join("|")}|${statusText}|${taskPlan?.id}:${taskPlan?.running}:${taskPlan?.steps.map(step => `${step.status}:${step.note.length}`).join(",")}`,
    [messages, taskPlan, statusText],
  )

  if (restoring || failedToRestore) {
    return (
      <div className="relative flex h-full min-h-0 items-center justify-center bg-background" data-ai-chat-overlay>
        {failedToRestore ? (
          <div className="flex flex-col items-center gap-3 text-sm">
            <p role="alert" className="text-muted-foreground">{restoreFailure?.message || "Could not load project."}</p>
            <Button variant="ghost" size="sm" onClick={() => setRestoreAttempt(attempt => attempt + 1)}>Retry</Button>
          </div>
        ) : <Spinner aria-label="Loading project" className="text-muted-foreground" />}
      </div>
    )
  }

  return (
    <div
      className="relative flex h-full min-h-0 flex-col overflow-hidden bg-background"
      data-ai-chat-overlay
    >
      <AiTranscriptScroll scrollKey={transcriptScrollKey}>
        <AiQuotaScope key={`chat:${chatId ?? "new"}`} scope={`chat:${chatId ?? "new"}`}>
        {hasMore?<Button type="button" variant="ghost" size="sm" onClick={()=>void loadEarlier()} disabled={loadingEarlier || busy}>{loadingEarlier?"Loading…":"Load earlier messages"}</Button>:null}
        {showIntro ? (
          <div className="flex min-h-full flex-1 flex-col items-center justify-center">
            <Empty className="border-0 md:p-6">
              <EmptyHeader>
                <EmptyTitle className="text-xl">
                  {settings.configured
                    ? "How can I help you today?"
                    : "AI assistant is not configured"}
                </EmptyTitle>
                <EmptyDescription>
                  {settings.configured
                    ? "Ask me to create a map, build a database from CSV, or explain how MapSVG works. You can also create a map manually using the button below."
                    : "Activate your MapSVG license in Usage to use your included AI credits."}
                </EmptyDescription>
              </EmptyHeader>
              {!settings.configured ? <Button type="button" variant="outline" onClick={() => window.dispatchEvent(new Event("mapsvg:open-usage"))}>Activate AI</Button> : null}
              {startScreenActions}
            </Empty>
          </div>
        ) : (
          messages.filter(message => message.role !== "tool" && message.content).map(message => (
            <div key={message.id} className="shrink-0">
              <AiConversationMessage
                messageId={message.id}
                role={message.role as "user" | "assistant"}
                content={message.content}
                isAnimating={busy && streamingIdRef.current === message.id}
              />
            </div>
          ))
        )}
        <AiCurrentStep label={progressLabel} />
        <AiQuotaWarning enabled={settings.configured} refreshKey={busy} />
        </AiQuotaScope>
      </AiTranscriptScroll>

      {!showIntro && startScreenActions ? (
        <div className="flex shrink-0 justify-center px-4 py-2">{startScreenActions}</div>
      ) : null}

      <AiChatComposer
        value={input}
        disabled={busy || restoring || !settings.configured}
        error={error}
        onChange={setInput}
        onSubmit={send}
      />
    </div>
  )
}
