/** One transient activity line; the moving text highlight is the progress indicator. */
export function AiCurrentStep({ label }: { label: string | null }) {
  if (!label) return null
  return (
    <div
      role="status"
      aria-live="polite"
      aria-atomic="true"
      data-slot="ai-current-step"
      className="min-w-0 shrink-0 px-1 py-0.5 text-sm text-muted-foreground"
    >
      <span className="mapsvg-ai-current-step-label inline-block max-w-full truncate align-bottom" title={label}>
        {label}
      </span>
    </div>
  )
}
