import { useEffect, useState } from "react"
import { getBootAiSettings } from "./ai-api"

/** Keep retained chats synchronized with successful license mutations. */
export function useBootAiSettings() {
  const [settings, setSettings] = useState(getBootAiSettings)
  useEffect(() => {
    const refresh = () => setSettings(getBootAiSettings())
    window.addEventListener("mapsvg:license-changed", refresh)
    return () => window.removeEventListener("mapsvg:license-changed", refresh)
  }, [])
  return settings
}
