import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react"
import { AlertTriangle, X } from "lucide-react"
import { Alert, AlertTitle, AlertDescription } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { getAiUsage, MapSVGApiError, type AiUsageLicense } from "@/lib/global-settings-api"
import { openAiCreditPacks } from "@/lib/ai-usage-navigation"

export const QUOTA_ERROR_PREFIX = "Error: Not enough AI credits for this request."

// Non-secret, browser-local presentation state. The server still owns admission.
const memoryStorage = new Map<string, string>()
function readNotice(key: string) {
  try {
    return localStorage.getItem(key)
  } catch {
    return memoryStorage.get(key) ?? null
  }
}
function writeNotice(key: string, value: string) {
  try {
    localStorage.setItem(key, value)
  } catch {
    memoryStorage.set(key, value)
  }
}
// Only the fresh server snapshot after confirmed fulfillment clears purchase
// notices. Ordinary polls with existing funds must not hide a rejected request.
function fundedPurchase(event: Event): AiUsageLicense | null {
  if (
    !(event instanceof CustomEvent) ||
    event.detail?.purchaseCompleted !== true ||
    !Array.isArray(event.detail.licenses)
  )
    return null
  const license = event.detail.licenses[0] as AiUsageLicense | undefined
  return license?.id &&
    license.aiAvailable &&
    Number.isFinite(license.purchasedRemaining) &&
    (license.purchasedRemaining ?? 0) > 0
    ? license
    : null
}
const QuotaScope = createContext<{
  scope: string
  redVisible: boolean
  errorRevision: number
  report: (id: string, visible: boolean) => void
} | null>(null)

export function AiQuotaScope({ scope, children }: { scope: string; children: ReactNode }) {
  const [state, setState] = useState({ ids: new Set<string>(), revision: 0 })
  const report = useCallback((id: string, visible: boolean) => {
    setState((previous) => {
      if (previous.ids.has(id) === visible) return previous
      const ids = new Set(previous.ids)
      if (visible) ids.add(id)
      else ids.delete(id)
      return { ids, revision: previous.revision + (visible ? 1 : 0) }
    })
  }, [])
  const value = useMemo(
    () => ({ scope, redVisible: state.ids.size > 0, errorRevision: state.revision, report }),
    [scope, state, report],
  )
  return <QuotaScope.Provider value={value}>{children}</QuotaScope.Provider>
}
function CloseNotice({ label, onClose }: { label: string; onClose: () => void }) {
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      className="absolute right-1 top-1 size-6"
      aria-label={label}
      onClick={onClose}
    >
      <X className="size-3.5" />
    </Button>
  )
}
export function AiQuotaError({ messageId }: { messageId?: string }) {
  const context = useContext(QuotaScope)
  const localId = useId()
  const id = messageId ?? localId
  const key = messageId ? `mapsvg:ai-quota:error:${context?.scope ?? "chat"}:${messageId}` : null
  const [dismissedKey, setDismissedKey] = useState<string | null>(null)
  const closed = dismissedKey === (key ?? id) || Boolean(key && readNotice(key) === "closed")
  const close = useCallback(() => {
    if (key) writeNotice(key, "closed")
    setDismissedKey(key ?? id)
  }, [key, id])
  useEffect(() => {
    const updated = (event: Event) => {
      if (fundedPurchase(event)) close()
    }
    window.addEventListener("mapsvg:ai-usage-updated", updated)
    return () => window.removeEventListener("mapsvg:ai-usage-updated", updated)
  }, [close])
  const report = context?.report
  useLayoutEffect(() => {
    report?.(id, !closed)
    return () => report?.(id, false)
  }, [id, closed, report])
  if (closed) return null
  return (
    <Alert variant="destructive" role="alert">
      <AlertTriangle />
      <AlertTitle className="pr-6">Not enough AI credits</AlertTitle>
      <AlertDescription>
        <p>
          This request needs more AI credits than are currently available. Buy credits or wait for
          your plan quota to reset.
        </p>
        <Button type="button" variant="outline" onClick={openAiCreditPacks}>
          Buy AI credits
        </Button>
      </AlertDescription>
      <CloseNotice label="Close AI credits error" onClose={close} />
    </Alert>
  )
}

export function AiQuotaWarning({ enabled, refreshKey }: { enabled: boolean; refreshKey: boolean }) {
  const [license, setLicense] = useState<AiUsageLicense | null>(null)
  const context = useContext(QuotaScope)
  const redVisible = context?.redVisible ?? false
  const errorRevision = context?.errorRevision ?? 0
  const handledError = useRef(0)
  const shown = useRef<{ key: string; threshold: 10 | 3 } | null>(null)
  const [notice, setNotice] = useState<{ key: string; threshold: 10 | 3 } | null>(null)
  useEffect(() => {
    if (!enabled) {
      setLicense(null)
      return
    }
    let disposed = false,
      pending = false
    const refresh = async () => {
      if (pending || document.hidden) return
      pending = true
      try {
        const data = await getAiUsage()
        if (!disposed) setLicense(data.licenses[0] ?? null)
      } catch (error) {
        if (!disposed && error instanceof MapSVGApiError && [401, 403].includes(error.status))
          setLicense(null)
      } finally {
        pending = false
      }
    }
    const updated = (event: Event) => {
      if (!disposed && event instanceof CustomEvent && Array.isArray(event.detail?.licenses)) {
        const purchased = fundedPurchase(event)
        if (purchased) {
          if (purchased.startsAt)
            writeNotice(`mapsvg:ai-quota:warning:${purchased.id}:${purchased.startsAt}`, "3")
          shown.current = null
          setNotice(null)
        }
        setLicense(event.detail.licenses[0] ?? null)
      }
    }
    window.addEventListener("mapsvg:ai-usage-updated", updated)
    void refresh()
    const timer = window.setInterval(() => void refresh(), 30_000)
    window.addEventListener("focus", refresh)
    window.addEventListener("mapsvg:license-changed", refresh)
    return () => {
      disposed = true
      window.removeEventListener("mapsvg:ai-usage-updated", updated)
      window.clearInterval(timer)
      window.removeEventListener("focus", refresh)
      window.removeEventListener("mapsvg:license-changed", refresh)
    }
  }, [enabled, refreshKey])
  const valid =
    enabled &&
    license?.aiAvailable &&
    Number.isFinite(license.allowance) &&
    license.allowance > 0 &&
    Number.isFinite(license.remaining)
  const key =
    valid && license.id && license.startsAt
      ? `mapsvg:ai-quota:warning:${license.id}:${license.startsAt}`
      : null
  const ratio = valid ? license.remaining / license.allowance : 1
  const threshold = ratio > 0 && ratio < 0.03 ? 3 : ratio > 0 && ratio < 0.1 ? 10 : null
  useEffect(() => {
    const clear = () => {
      shown.current = null
      setNotice(null)
    }
    if (!key) {
      clear()
      return
    }
    // Red is the final escalation for this period. Closing it must not reveal
    // a lower-priority yellow notice, even if usage arrived after the close.
    if (redVisible || errorRevision > handledError.current) {
      writeNotice(key, "3")
      handledError.current = errorRevision
      clear()
      return
    }
    if (!threshold) {
      clear()
      return
    }
    if (shown.current?.key === key && shown.current.threshold === threshold) return
    const seen = readNotice(key)
    if (seen === "3" || (threshold === 10 && seen === "10")) {
      clear()
      return
    }
    writeNotice(key, String(threshold))
    shown.current = { key, threshold }
    setNotice(shown.current)
  }, [key, threshold, redVisible, errorRevision])
  if (!license || !notice || notice.key !== key || notice.threshold !== threshold || redVisible)
    return null
  const period = { daily: "daily", weekly: "weekly", monthly: "monthly", annual: "annual" }[
    license.periodKind
  ]
  return (
    <div className="shrink-0">
      <Alert role="status" variant="warning">
        <AlertTriangle />
        <AlertTitle className="pr-6">Your AI limit is almost reached</AlertTitle>
        <AlertDescription>
          <p>
            Less than {notice.threshold}% of your {period} AI allowance remains.
            {(license.purchasedRemaining ?? 0) > 0
              ? " Purchased credits are available after your plan allowance."
              : " Buy credits to keep using AI."}
          </p>
          <Button type="button" variant="outline" onClick={openAiCreditPacks}>
            Buy AI credits
          </Button>
        </AlertDescription>
        <CloseNotice
          label="Close AI quota warning"
          onClose={() => {
            shown.current = null
            setNotice(null)
          }}
        />
      </Alert>
    </div>
  )
}
