import "./styles.css"
import {fetchProjectChats,updateAiChat,createAiChat} from "./lib/ai-api"
import { AiChatPanel } from "./components/ai/AiChatPanel"
import { AiStartScreen } from "./components/ai/AiStartScreen"
import { TooltipProvider } from "@/components/ui/tooltip"

function AiAssistantPanel({ mapId }: { mapId?: number | null }) {
  return (
    <TooltipProvider delayDuration={400}>
      <AiChatPanel mapId={mapId} />
    </TooltipProvider>
  )
}

const host = window.MapSVG?.extensions
if (!host) {
  throw new Error("[MapSVG AI Assistant] Shared extension host is not available")
}

host.registerCapability("ai_assistant", {
  family: "ai_assistant",
  source: "paid/features/ai_assistant",
})

host.register("admin.panel", "ai", {
  id: "ai",
  Panel: AiAssistantPanel,
})

host.register("admin.panel", "ai-start-screen", {
  id: "ai-start-screen",
  Panel: AiStartScreen,
  projectChats:{list:fetchProjectChats,rename:(id:number,title:string)=>updateAiChat(id,{title}),attachMap:(chatId:number|null,mapId:number)=>chatId?updateAiChat(chatId,{mapId}):createAiChat({mapId})},
})
